\begin{hypothesis}[H1: Projection Structure]\label{hyp:H1}
Let $\Hilb$ be a real Hilbert space with inner product $\inner{\cdot}{\cdot}$ and norm $\norm{\cdot}$. Let $\I \subset \Hilb$ be non-empty, closed, and convex.
\end{hypothesis}

\begin{hypothesis}[H2: Contraction Operator]\label{hyp:H2}
Let $K:\Hilb\to\Hilb$ be a bounded linear operator with operator norm $\norm{K}<1$.
\end{hypothesis}

\begin{hypothesis}[H3: Completeness]\label{hyp:H3}
The ambient space $\Hilb$ is complete.
\end{hypothesis}

\begin{hypothesis}[H4: Parameter Compactness]\label{hyp:H4}
Let $\U$ be a compact metric space and let $\Gamma:\U\to\Hilb$ be uniformly continuous.
\end{hypothesis}

\begin{proposition}[Base sufficiency of H1--H4]\label{prop:minimal}
Hypotheses H1--H4 are sufficient for:
\begin{enumerate}[leftmargin=*]
\item existence and uniqueness of the metric projection onto $\I$;
\item strict contraction of the transition operators $T_u$;
\item existence and uniqueness of the fixed point $f_u^\ast$ for each $u\in\U$;
\item compactness of the attractor family $\A^\ast=\{f_u^\ast:u\in\U\}$.
\end{enumerate}
They do not, by themselves, imply parameterwise non-collapse.
\end{proposition}

\begin{definition}[Metric Projection]\label{def:projection}
For $\Psi\in\Hilb$, define the metric projection onto $\I$ by
\[
\aleph(\Psi):=\arg\min_{\Phi\in\I}\norm{\Psi-\Phi}.
\]
\end{definition}

\begin{theorem}[Existence and Uniqueness of Projection]\label{thm:projection}
Under Hypothesis~\ref{hyp:H1}, the projection $\aleph(\Psi)$ exists and is unique for every $\Psi\in\Hilb$.
\end{theorem}

\begin{lemma}[Non-Expansiveness of the Projection]\label{lem:nonexp}
The map $\aleph:\Hilb\to\I$ is non-expansive:
\[
\norm{\aleph(\Psi_1)-\aleph(\Psi_2)}\le \norm{\Psi_1-\Psi_2}
\qquad
\forall \Psi_1,\Psi_2\in\Hilb.
\]
\end{lemma}

\begin{definition}[Transition Operator]\label{def:transition}
For each $u\in\U$, define
\[
T_u(\Psi):=\aleph(K\Psi+\Gamma(u)).
\]
\end{definition}

\begin{theorem}[Contractivity]\label{thm:contraction}
Under Hypotheses~\ref{hyp:H1} and \ref{hyp:H2}, each $T_u$ is a strict contraction with Lipschitz constant at most $\norm{K}$:
\[
\norm{T_u(\Psi_1)-T_u(\Psi_2)}\le \norm{K}\,\norm{\Psi_1-\Psi_2}.
\]
\end{theorem}

\begin{definition}[Attractor Family]\label{def:attractor}
Define the attractor family
\[
\A^\ast:=\{f_u^\ast:u\in\U\}.
\]
\end{definition}

\begin{theorem}[Compactness of the Attractor Family]\label{thm:compactness}
Under Hypotheses~\ref{hyp:H1}--\ref{hyp:H4}, the set $\A^\ast$ is compact in $\Hilb$.
\end{theorem}

\begin{definition}[Constant Subspace]
Whenever the ambient realization distinguishes constant elements, let $\mathcal{N}\subset\Hilb$ denote the closed subspace of constants.
\end{definition}

\begin{hypothesis}[H5: No Constant Fixed Points]\label{hyp:H5}
For every parameter $u\in\U$ and every constant element $c\in\mathcal{N}$,
\[
T_u(c)\neq c.
\]
\end{hypothesis}

\begin{theorem}[Structural Non-Collapsibility]\label{thm:noncollapse}
Under Hypotheses~\ref{hyp:H1}--\ref{hyp:H5}, the family is parameterwise non-collapsible:
\[
f_u^\ast\notin\mathcal{N}
\qquad
\forall u\in\U.
\]
\end{theorem}

\begin{remark}[What H5 does not say]
Hypothesis~\ref{hyp:H5} is parameterwise. It does not merely say that \emph{some} parameter breaks constant collapse. It excludes constant fixed points for \emph{every} parameter. This is exactly the quantifier strength needed for Theorem~\ref{thm:noncollapse}.
\end{remark}

\begin{remark}[Typing discipline]
No unembedded element of $E$ is treated as an element of $\mathcal{B}$. The embedding $j$ is always written explicitly. This removes the earlier type leak in which a disk in $E$ was silently treated as a subset of a function space.
\end{remark}

\begin{lemma}[The Disk Projection is Non-Expansive]\label{lem:disk-projection}
For all $v,w\in E$,
\[
\norm{P_E(v)-P_E(w)}_2\le \norm{v-w}_2.
\]
\end{lemma}

\begin{proposition}[Typed Non-Vacuity of the Computable Model]\label{prop:Q3verify}
The embedded constant-disk Golden Mean model is a fully typed, non-vacuous witness of the transition grammar:
\begin{enumerate}[leftmargin=*]
\item every operator has explicit domain and codomain;
\item the transition map $T_u$ is well-defined on $\mathcal{B}$;
\item the family admits unique fixed points and a compact parameter image;
\item the state contraction bound is explicit and computable.
\end{enumerate}
\end{proposition}

\begin{remark}[Why this witness does not certify H5]
The image of $T_u$ lies in the constant subspace $\mathcal{I}_{\mathrm c}$. Therefore its fixed point is constant by construction. This witness is correct and useful for typing and state spectral analysis, but it cannot certify the parameterwise anti-constant hypothesis H5 from Section~\ref{sec:parameterwise-noncollapse}.
\end{remark}

\begin{proposition}[Separate Witness for H5]
The family $\{T_u^{\mathrm{ac}}\}_{u\in\U}$ satisfies Hypotheses~\ref{hyp:H1}--\ref{hyp:H5} of Section~1.
\end{proposition}

\begin{remark}
BaseCore therefore distinguishes two roles cleanly: the Golden Mean witness certifies typed operator correctness and state contraction; the affine anti-collapse witness certifies the stronger H5 burden needed for parameterwise non-collapse.
\end{remark}

\begin{theorem}[Relaxation-Time Bound]\label{thm:relaxation}
Under the hypotheses of Theorem~\ref{thm:spectrum}, any discrete-to-continuous relaxation convention of the form
\[
\tau_{\mathrm{state}}=-\frac{1}{\ln \rho}
\]
with $\rho=\rho(DT_u(f_u^\ast))$ gives
\[
\tau_{\mathrm{state}}\le \frac{1}{\ln 2}.
\]
\end{theorem}

\begin{proposition}[Parameter-Family Persistence is not State Spectrum]
Let $F:\U\to\mathcal{B}$ be the fixed-point family $F(u)=f_u^\ast$. Any persistence of parameter labels or family coordinates belongs to the variation of $F$ over $\U$, not to the state-transition spectrum of $DT_u(f_u^\ast)$ for fixed $u$.
\end{proposition}

\begin{remark}[What has been removed]
The previous text incorrectly mixed strict contraction with a state-spectrum eigenvalue $\lambda=1$. BaseCore no longer does that. Any neutral or persistent mode must now be interpreted as a parameter-family bookkeeping mode, not as an eigenmode of the contractive state Jacobian.
\end{remark}

\begin{remark}[Identity neutrality]
In BaseCore, $\Id$ is a structural inverse-limit object only. It carries no automatic phenomenological, biological, or metaphysical interpretation.
\end{remark}

\begin{hypothesis}[Topological Regularity]\label{hyp:topo}
Each $S_t$ is compact Hausdorff and each $\pi_{t+1\to t}$ is continuous and surjective.
\end{hypothesis}

\begin{remark}[Persistent future branching as an operational form of NFD]
A sufficient operational strengthening of Hypothesis~\ref{hyp:nfd} is: for every $t$ there exists $k>t$ and $x_t\in S_t$ such that the fiber of $\pi_{k\to t}$ over $x_t$ contains at least two globally extendable compatible histories. BaseCore keeps the weaker NFD statement as the primary assumption because it is exactly what the non-locality theorem needs.
\end{remark}

\begin{remark}[What is \emph{not} proved here]
BaseCore does not prove that no arbitrary set-theoretic injection $\Id\to S_t$ can exist in every imaginable inverse system. It proves the narrower and correct claim that the canonical projective observations $p_t$ are not injective under Hypothesis~\ref{hyp:nfd}.
\end{remark}

\begin{proposition}[No Canonical Progressive Recovery under NFD]\label{thm:noprogressive}
Assume Hypothesis~\ref{hyp:nfd}. No finite canonical prefix map determines the inverse-limit identity object.
\end{proposition}

\begin{assumption}[RIG-1: Metric Projective System]\label{ass:rig1}
Each $S_t$ is equipped with a complete metric $d_t$.
\end{assumption}

\begin{assumption}[RIG-2: Uniform Lipschitz Projections]\label{ass:rig2}
Each projection $\pi_{t+1\to t}:S_{t+1}\to S_t$ is Lipschitz with constant $L_t$, and the weighted control sequence used below is finite.
\end{assumption}

\begin{assumption}[RIG-3: Stable Lifting]\label{ass:rig3}
For each admissible perturbed projection family there exist compatible approximate lifting maps with constants bounded uniformly by a finite lifting constant $L_{\mathrm{lift}}$.
\end{assumption}

\begin{assumption}[RIG-5: Summable Deformation]\label{ass:rig5}
There exists a positive weight sequence $\{w_t\}_{t\ge 0}$ such that
\[
\sum_{t=0}^\infty w_t\eps_t<\infty.
\]
\end{assumption}

\begin{corollary}[Conditional Isomorphism Requires Extra Structure]
The metric estimate of Theorem~\ref{thm:rigidity} does not by itself imply that $\Id$ and $\widetilde{\Id}$ are isomorphic. Isomorphism or shape-equivalence requires additional bi-lifting, coherence, or ambient-embedding assumptions.
\end{corollary}

\begin{definition}[Ontological Mass]\label{def:ontmass}
Let $E_w(\delta)$ denote the weighted energy of an admissible perturbation family $\delta$. Define
\[
\MO:=\inf\left\{
\frac{E_w(\delta)}{d_H(\Id,\widetilde{\Id}_\delta)}
\;\middle|\;
\delta \text{ admissible},\ d_H(\Id,\widetilde{\Id}_\delta)>0
\right\},
\]
with the convention $\MO=+\infty$ if no admissible finite-energy perturbation yields positive deformation of the identity object.
\end{definition}

\begin{remark}[Interpretation discipline]
$\MO$ is a deformation-resistance scalar, not a metaphysical substance. BaseCore uses it only as a conditional invariant attached to admissible perturbation models.
\end{remark}

\begin{assumption}[NS-1: CCR Target]\label{ass:ns1}
A CCR target is an inverse-limit identity object satisfying:
\begin{enumerate}[leftmargin=*]
\item non-finite determination (Hypothesis~\ref{hyp:nfd});
\item infinite deformation resistance $\MO=+\infty$;
\item absence of a finite sufficient statistic for faithful identity recovery;
\item absence of a finite-dimensional faithful embedding preserving projective compatibility.
\end{enumerate}
\end{assumption}

\begin{assumption}[NS-2: Finite Simulator Class]\label{ass:ns2}
A simulator $C$ belongs to $\mathbf{Comp}_{\mathrm{finite}}$ if it has at least one of the following boundedness features:
\begin{enumerate}[leftmargin=*]
\item finite-dimensional latent state or finite context;
\item bounded memory horizon or finite sufficient statistic;
\item finite perturbation-energy budget;
\item finite-rank projective representation.
\end{enumerate}
\end{assumption}

\begin{assumption}[NS-3: Faithful Simulation Requirement]\label{ass:ns3}
A simulation is faithful only if it preserves, at the stated tolerance level, all of:
\begin{enumerate}[leftmargin=*]
\item projective compatibility;
\item non-finite determination;
\item deformation-resistance class;
\item relevant observables in the weighted metric;
\item admissible intervention responses.
\end{enumerate}
\end{assumption}

\begin{theorem}[Conditional Non-Simulability of CCR by Finite Simulators]\label{thm:non-simulability}
Assume NS-1 through NS-3. Then no simulator in $\mathbf{Comp}_{\mathrm{finite}}$ faithfully realizes a CCR target.
\end{theorem}

\begin{theorem}[Approximation Barrier]
Assume NS-1 through NS-3. Finite simulators may approximate bounded finite projections of a CCR target over finite horizons, but they cannot preserve the full inverse-limit object faithfully as the horizon grows without bound unless resources also grow without bound.
\end{theorem}

\begin{remark}[What has been removed]
BaseCore no longer claims that finite simulators ``cannot approximate at all.'' The correct statement is conditional and finer-grained: finite-horizon approximation may exist, but faithful full inverse-limit realization of CCR targets is blocked under NS-1 through NS-3.
\end{remark}

\begin{definition}[Phenomenological Space]\label{def:phenspace}
A phenomenological space is a nonempty set $\mathcal{E}$ whose elements are called \textit{phenomenological configurations}. No topology, metric, or algebraic structure is assumed a priori.
\end{definition}

\begin{remark}
We do not claim that $\mathcal{E}$ represents ``conscious states'' or ``qualia''. It is an abstract mathematical space whose interpretation is not specified by the formalism. The space $\mathcal{E}$ is introduced purely as the codomain of a structural assignment; its ontological status is deliberately left open.
\end{remark}

\begin{proposition}[Non-Triviality of Phenomenological Codomain]
If phenomenological assignments were required to land in $\mathcal{I}$ itself, then any compatible assignment would be the identity map, eliminating all non-trivial phenomenological structure.
\end{proposition}

\begin{definition}[Phenomenological Assignment]\label{def:phenassign}
A phenomenological assignment is a family of partial maps:
\begin{equation}
    \phi_t: S_t \to \mathcal{E}
\end{equation}
indexed by $t \in \mathbb{N}$.
\end{definition}

\begin{definition}[Induced Limit Assignment]\label{def:limitassign}
Given a phenomenological assignment $\{\phi_t\}$, the induced limit assignment is the partial map:
\begin{equation}
    \Phi: \mathcal{I} \to \mathcal{E}, \quad \Phi((x_t)_t) := \lim_{t \to \infty} \phi_t(x_t),
\end{equation}
whenever the limit exists in an appropriate sense (to be defined by compatibility axioms).
\end{definition}

\begin{proposition}[Uniqueness of Compatible $\Phi$]\label{prop:unique-phi}
Given a compatible family $\{\phi_t\}$ satisfying E1, the induced limit assignment $\Phi$ is unique.
\end{proposition}

\begin{axiom}[E0: Non-Triviality]\label{ax:e0}
The phenomenological space satisfies $|\mathcal{E}| \geq 2$, i.e., there exist at least two distinct phenomenological configurations.
\end{axiom}

\begin{axiom}[E1: Projective Compatibility]\label{ax:e1}
For every compatible identity trajectory $(x_t)_t \in \mathcal{I}$, the induced phenomenological sequence satisfies:
\begin{equation}
    \phi_{t+1}(x_{t+1}) = \phi_t(x_t) \quad \forall t.
\end{equation}
\end{axiom}

\begin{axiom}[E2: Non-Locality]\label{ax:e2}
There exists no function $f: S_t \to \mathcal{E}$ (for any fixed $t$) such that for all trajectories $(x_t)_t \in \mathcal{I}$:
\begin{equation}
    \Phi((x_t)_t) = f(x_t).
\end{equation}
\end{axiom}

\begin{theorem}[E0 is Necessary]\label{thm:e0-necessary}
If $|\mathcal{E}| = 1$, then every phenomenological assignment is constant and no phenomenological classification is possible.
\end{theorem}

\begin{theorem}[E1 is Necessary]\label{thm:e1-necessary}
If E1 fails, then phenomenological assignments are incompatible with the inverse-limit structure of identity, and no coherent $\Phi: \mathcal{I} \to \mathcal{E}$ can be defined.
\end{theorem}

\begin{theorem}[E2 is Necessary]\label{thm:e2-necessary}
If E2 fails, then phenomenology is a local property of states, contradicting the global nature of identity as an inverse limit.
\end{theorem}

\begin{theorem}[Axiomatic Minimality]\label{thm:minimality}
The axiom set $\{E0, E1, E2\}$ is minimal: no proper subset is sufficient to derive the main results of this paper.
\end{theorem}

\begin{definition}[Phenomenological Compatibility Class]\label{def:compat-class}
For a given $M_\Omega$, define the phenomenological compatibility class:
\begin{equation}
    \mathcal{P}(M_\Omega) := \left\{ \Phi: \mathcal{I} \to \mathcal{E} \;\Big|\; \Phi \text{ satisfies E0--E2} \right\}.
\end{equation}
\end{definition}

\begin{remark}
The compatibility class $\mathcal{P}(M_\Omega)$ is the set of all phenomenological assignments that are structurally admissible given the identity's rigidity. Note that $\mathcal{P}(M_\Omega)$ depends only on the structural properties of identity, not on any phenomenological primitives.
\end{remark}

\begin{hypothesis}[H3: Metric on $\mathcal{E}$]\label{hyp:h3}
The phenomenological space $\mathcal{E}$ admits a metric $d_\mathcal{E}$ such that $(\mathcal{E}, d_\mathcal{E})$ is a complete metric space.
\end{hypothesis}

\begin{theorem}[H3 is Necessary for Impossibility Theorems]\label{thm:h3-necessary}
Without a metric structure on $\mathcal{E}$, the notions of phenomenological continuity, fragmentation, and loss capacity cannot be defined.
\end{theorem}

\begin{proposition}[Completeness is Necessary for Forced Continuity]\label{prop:complete-necessary}
If $(\mathcal{E}, d_\mathcal{E})$ is not complete, then the Forced Continuity Theorem (Theorem~\ref{thm:forced-continuity}) may fail.
\end{proposition}

\begin{definition}[Phenomenological Continuity]\label{def:phen-continuity}
A phenomenological assignment $\Phi: \mathcal{I} \to \mathcal{E}$ is \textit{structurally continuous} if for every sequence $(x^{(n)})_n$ in $\mathcal{I}$ converging in the $d_w$ metric:
\begin{equation}
    d_w(x^{(n)}, x) \to 0 \implies d_\mathcal{E}(\Phi(x^{(n)}), \Phi(x)) \to 0.
\end{equation}
\end{definition}

\begin{remark}
Structural continuity is not an axiom; it is a \textit{derived property} that follows from CCR conditions. This is the content of the Forced Continuity Theorem (Section 4).
\end{remark}

\begin{definition}[Phenomenological Fragmentation]\label{def:fragmentation}
A phenomenological assignment $\Phi$ is \textit{fragmentable} if there exists a perturbation $\{\epsilon_t\}$ with finite weighted energy such that:
\begin{equation}
    d_\mathcal{E}(\Phi(x), \tilde{\Phi}(\tilde{x})) > 0
\end{equation}
for corresponding identity trajectories $x \in \mathcal{I}$ and $\tilde{x} \in \tilde{\mathcal{I}}$.
\end{definition}

\begin{remark}
Fragmentation captures the vulnerability of phenomenological structure to perturbations. It is the phenomenological analog of identity deformability.
\end{remark}

\begin{proposition}[Metric Compatibility]\label{prop:metric-compat}
The metrics $d_w$ on $\mathcal{I}$ and $d_\mathcal{E}$ on $\mathcal{E}$ are compatible in the following sense: if E1 holds, then small $d_w$-changes in trajectories induce bounded $d_\mathcal{E}$-changes in phenomenological configurations (when $\Phi$ is continuous).
\end{proposition}

\begin{hypothesis}[$\Phi$-Regularity Lower Bound]\label{hyp:phi-regularity}
Let $(\mathcal{I}, d_w)$ be the identitary metric space from \textit{Rigid Identity} and let $(\mathcal{E}, d_\mathcal{E})$ be the abstract phenomenological metric space. A phenomenological assignment $\Phi: \mathcal{I} \to \mathcal{E}$ is said to satisfy $\Phi$-regularity when it satisfies:
\begin{enumerate}[leftmargin=*]
    \item (Properness) For every compact $K \subset \mathcal{E}$, $\Phi^{-1}(K)$ is compact in $\mathcal{I}$.
    \item (Local Lipschitz regularity) For every $x \in \mathcal{I}$, there exist $\varepsilon > 0$ and $L_x > 0$ such that for all $y, z \in B_\varepsilon(x)$:
    \begin{equation}
        d_\mathcal{E}(\Phi(y), \Phi(z)) \leq L_x \cdot d_w(y, z).
    \end{equation}
    \item (Non-collapse) For every $x \in \mathcal{I}$ and every $r > 0$, the restriction of $\Phi$ to $B_r(x)$ is not constant.
    \item (Global lower Lipschitz bound) There exists a constant $C>0$ such that for all $x,y\in\mathcal{I}$,
    \begin{equation}
        d_\mathcal{E}(\Phi(x),\Phi(y)) \geq C\cdot d_w(x,y).
    \end{equation}
\end{enumerate}
\end{hypothesis}

\begin{caveat}[Status of $\Phi$-regularity]
The fourth clause is an additional structural assumption, not a consequence of the first three clauses. The counterexample in Appendix~\ref{app:phi-regularity-counterexample} shows that properness, local Lipschitz regularity, and non-collapse do not imply any uniform lower Lipschitz constant.
\end{caveat}

\begin{theorem}[Fragmentation Theorem]\label{thm:fragmentation}
Let $\mathcal{I}$ be an identity object with $M_\Omega < \infty$. If a phenomenological assignment $\Phi \in \mathcal{P}(M_\Omega)$ satisfies Hypothesis~\ref{hyp:phi-regularity}, then $\Phi$ is fragmentable. That is:
\begin{equation}
    M_\Omega < \infty \ \wedge\ \Phi\text{ satisfies Hypothesis~\ref{hyp:phi-regularity}}
    \implies \Phi \in \mathcal{E}_{\text{frag}},
\end{equation}
where $\mathcal{E}_{\text{frag}}$ denotes the class of fragmentable phenomenological assignments.
\end{theorem}

\begin{corollary}[No Structural Continuity Guarantee for Finite Mass]
Systems with $M_\Omega < \infty$ cannot structurally prevent phenomenological discontinuity.
\end{corollary}

\begin{theorem}[Forced Continuity Theorem]\label{thm:forced-continuity}
Let $\mathcal{I}$ be an identity object with $M_\Omega = +\infty$ (CCR). Then every phenomenological assignment $\Phi \in \mathcal{P}(M_\Omega)$ is structurally continuous. That is:
\begin{equation}
    M_\Omega = +\infty \implies \mathcal{P}(M_\Omega) \subseteq \mathcal{E}_{\text{cont}},
\end{equation}
where $\mathcal{E}_{\text{cont}}$ denotes the class of structurally continuous phenomenological assignments.
\end{theorem}

\begin{corollary}[CCR Phenomenology is Invariant]
In CCR systems, any admissible phenomenological assignment is invariant under all finite-energy perturbations.
\end{corollary}

\begin{theorem}[Phenomenological Dichotomy]\label{thm:dichotomy}
Let $\Phi: \mathcal{I} \to \mathcal{E}$ be an admissible phenomenological assignment. Then exactly one of the following holds:
\begin{enumerate}[leftmargin=*]
    \item $M_\Omega < \infty$ and $\Phi$ is fragmentable;
    \item $M_\Omega = +\infty$ and $\Phi$ is structurally continuous.
\end{enumerate}
\end{theorem}

\begin{proposition}[Null Identity Excludes Persistent Phenomenology]
If $M_\Omega = 0$, then no admissible phenomenological assignment exists satisfying E0--E2.
\end{proposition}

\begin{proposition}[Deformable Identity Admits Only Fragmentable Phenomenology]
If $0 < M_\Omega < \infty$, every admissible phenomenological assignment is fragmentable under some finite-energy perturbation.
\end{proposition}

\begin{proposition}[Rigid Identity Forces Continuous Phenomenology]
If $M_\Omega = +\infty$, every admissible phenomenological assignment is structurally continuous and invariant under finite-energy perturbations.
\end{proposition}

\begin{lemma}[Phenomenology Inherits Rigidity]
If $\Phi: \mathcal{I} \to \mathcal{E}$ satisfies E0--E2 and $M_\Omega = +\infty$, then $\Phi$ inherits the rigidity of $\mathcal{I}$.
\end{lemma}

\begin{definition}[Phenomenological Attractor Set]\label{def:phenomenological-attractor}
For a channel $S$, define
\[
\Attr(S) := \{ e \in \E : e \text{ is stable under all compatible extensions and summable deformations} \}.
\]
\end{definition}

\begin{definition}[Phenomenological Stability]\label{def:phenomenological-stability}
A regime $e \in \E$ is \textbf{stable} for channel $S$ if for every compatible extension $S'$ of $S$ and every summable perturbation family $\{\epsilon_n\}$, the induced regime $\Phi_{S'}(\I')$ stays within a bounded $\dE$-neighborhood of $e$ controlled by $\|\{\epsilon_n\}\|_w$.
\end{definition}

\begin{lemma}[Bridge Lemma]\label{lem:null-bridge}
If $\Phi:\I\to\E$ is a compatibility operator for a CCR channel and $e=\Phi(\I)$ satisfies $\dE(e,\nullphi)=0$, then $e=\nullphi$.
\end{lemma}

\begin{corollary}[Forced Non-Nullity]\label{cor:forced-non-nullity}
Every CCR channel necessarily induces a regime $e_\star \in \E$ with $e_\star \succ \nullphi$.
\end{corollary}

\begin{definition}[Positive Regime Space]\label{def:positive-regime-space}
Define
\[
\Eplus := \{ e \in \E : e \succ \nullphi \}.
\]
\end{definition}

\begin{theorem}[Minimal Positive Regime]\label{thm:minimal-positive-regime}
For every CCR channel there exists a minimal positive regime $e_\star \in \Eplus$.
\end{theorem}

\begin{definition}[Structural Intensity]\label{def:structural-intensity}
For $e \in \Eplus$, define the structural intensity
\[
\iota(e) := \dE(e,\nullphi).
\]
\end{definition}

\begin{theorem}[Universal Intensity Bound]\label{thm:universal-intensity-bound}
If $e_\star$ is the minimal positive regime of a CCR channel, then there exist constants $C,\varepsilon_0>0$ such that
\[
\iota(e_\star) \ge C\varepsilon_0 > 0.
\]
\end{theorem}

\begin{theorem}[Forced Phenomenological Closure]\label{thm:forced-phenomenological-closure}
Every CCR system induces a unique minimal phenomenological regime that is non-null, stable, and quantitatively separated from $\nullphi$.
\end{theorem}

\begin{proposition}[Profinite Bound]\label{prop:profinite-bound}
In the profinite canonical family, the coupling lower bound induces a positive lower bound on the structural intensity of the minimal positive regime.
\end{proposition}

\begin{proposition}[Symbolic Bound]\label{prop:symbolic-bound}
In the symbolic canonical family, the Bowen-type metric induces the analogous positive lower bound for the minimal positive regime.
\end{proposition}

\begin{theorem}[Rigidity Inheritance]\label{thm:rigidity-inheritance}
If a subsystem or induced family preserves the CCR hypotheses and the compatibility operator, then the inherited regime structure preserves null-regime instability and forced non-nullity.
\end{theorem}

\begin{theorem}[Categorical Universality]\label{thm:null-categorical-universality}
The null-regime exclusion result is universal across admissible CCR realizations in the relevant category of compatible channels.
\end{theorem}

\begin{theorem}[Simulation Lower Bound]\label{thm:null-simulation-lower-bound}
Any computational system attempting to simulate the null-excluding CCR regime structure with arbitrary precision requires unbounded resources as the approximation error tends to zero.
\end{theorem}

\begin{theorem}[Closure by Non-Alternatives]\label{thm:null-closure-by-non-alternatives}
No admissible alternative closes the CCR regime structure while preserving null stability. Any admissible alternative either preserves the same closure structure or exits the CCR class.
\end{theorem}

\begin{definition}[BaseCore Envelope]
The BaseCore envelope is the collection of theorem-level structures owned directly by this source tree:
\begin{enumerate}[leftmargin=*]
\item foundational Hilbert-space projection dynamics;
\item typed computable witnesses and state spectral-gap bounds;
\item parameterwise non-collapse under explicit anti-constant assumptions;
\item inverse-limit identity under non-finite-determination assumptions;
\item conditional rigidity under admissible perturbation models;
\item conditional non-simulability of CCR targets by finite simulator classes;
\item operational-criterion grammar, certification, falsation, and claim-boundary ledgers.
\end{enumerate}
\end{definition}

\begin{proposition}[Boundary Discipline]
BaseCore may define structures that downstream layers use, but it does not claim downstream closure. In particular, BaseCore does not by itself own runtime thresholds, bridge admissibility, human-comparator programs, phenomenality burdens, or Papers 7--9.
\end{proposition}

\begin{remark}[Why the earlier material was removed from BaseCore ownership]
Previous versions mixed theorem-tight base results with runtime-like numerics, non-convex extension classes, and bridge-facing vocabulary. That blurred the mathematical base layer. BaseCore now keeps only the theorem ownership that survives the stricter release gate.
\end{remark}

\begin{definition}[Downstream admissible extension]
A downstream layer is an admissible extension of a BaseCore export object $\mathfrak{E}$ only if it supplies:
\begin{enumerate}[leftmargin=*]
\item an explicit target predicate $P$ not already contained in $\mathcal{R}$;
\item a typed construction or estimator witnessing the objects on which $P$ is evaluated;
\item a proof, reduction, or reproducible protocol connecting $\mathcal{H}$ to $P$;
\item negative controls or failure modes under which $P$ must not be asserted;
\item a provenance statement distinguishing theorem, implementation, internal support, and external adjudication.
\end{enumerate}
\end{definition}

\begin{proposition}[No automatic downstream promotion]
Let $\mathfrak{E}=(\mathcal{O},\mathcal{H},\mathcal{R},\mathcal{B})$ be a BaseCore export object and let $P$ be a predicate introduced outside BaseCore. If $P\notin\mathcal{R}$, then BaseCore does not entail $P$ unless an admissible extension supplies an additional bridge from $\mathcal{H}$ to $P$.
\end{proposition}

\begin{criterion}[Runtime-use admissibility]
A runtime measurement may instantiate a BaseCore export object only as an implementation-level witness when all of the following are recorded: the measured state space, the estimator or update rule, the finite horizon, the calibration regime, the controls under which the measurement fails, and the claim class being asserted. Such a measurement is not a BaseCore theorem and is not external validation by itself.
\end{criterion}

\begin{remark}[Open-load placement for $I_{\mathrm{int}}$ and atomic separators]
Quantities such as $I_{\mathrm{int}}$ and any atomic-separator condition may be treated as downstream target predicates or estimator families only after their carrier objects, separator class, invariance target, and negative controls are specified. Until a proof or reproducible adversarial protocol closes that burden, BaseCore may export the ambient structural language but not the separator conclusion.
\end{remark}

\begin{proposition}[Boundary preservation under finite implementations]
Suppose a finite implementation produces diagnostics for a downstream predicate $P$ over a bounded horizon. If the implementation does not prove that the diagnostics are invariant over the relevant mathematical class, then the diagnostics remain implementation evidence for $P$ and do not promote $P$ to a BaseCore result.
\end{proposition}

\begin{definition}[Admissible system]\label{def:system}
An admissible system is a tuple
\[
S=(X,\Phi,C,R,\Gamma,U)
\]
where:
\begin{enumerate}[leftmargin=1.5em]
\item $X$ is a metrizable internal state space with metric $d_X$;
\item $\Phi=\{\Phi_u\}_{u\in U}$ is a family of admissible transition operators $\Phi_u:X\to X$;
\item $C$ is the effective causal structure used to test admissible factorization and intervention behavior;
\item $R=\{r_\alpha\}_{\alpha\in\Lambda_R}$ is a family of readouts, each $r_\alpha:X\to Y_\alpha$;
\item $\Gamma=\{\gamma_j\}_{j=1}^m$ is an admissibility bundle defining
\[
X_\Gamma=\{x\in X:\gamma_j(x)\le 0\ \forall j\};
\]
\item $U$ is the set of admissible interventions.
\end{enumerate}
\end{definition}

\begin{definition}[Admissible support]\label{def:support}
A subset $\Aset\subseteq X_\Gamma$ is an admissible support if:
\begin{enumerate}[leftmargin=1.5em]
\item $\Aset$ is non-empty and compact;
\item $\Phi_u(\Aset)\subseteq \Aset$ for every $u\in U$;
\item $\Aset\cap \Attr(S)\neq\varnothing$;
\item $\Aset$ stays disjoint from the collapse set excluded by the base non-collapse burden.
\end{enumerate}
\end{definition}

\begin{definition}[Operational partition candidate]\label{def:partition}
An operational partition candidate is a map
\[
\pi_{S,T}:\Hist_{S,T}\to \Class_{S,T}
\]
into a finite or countable label set $\Class_{S,T}$.
\end{definition}

\begin{definition}[Structural persistence]\label{def:iper}
An admissible system satisfies structural persistence, written $\Iper(S)=1$, if there exists an admissible support $\Aset$ and a constant $\delta_{\mathrm{per}}(S)>0$ such that:
\begin{enumerate}[leftmargin=1.5em]
\item $\Aset$ is forward invariant under all $u\in U$;
\item every admissible trajectory starting in $\Aset$ remains at least $\delta_{\mathrm{per}}(S)$ away from the collapse set;
\item $\Aset$ contains or converges into a non-empty admissible attractor region.
\end{enumerate}
\end{definition}

\begin{definition}[Rigid identity]\label{def:iri}
An admissible system satisfies rigid identity, written $\Iri(S)=1$, if the observable family induced by $R$ on $\Aset$ determines a unique identity object $\Id_S$ and there exists a gap $\delta_{\mathrm{ri}}(S)>0$ such that every admissible alternative identity candidate remains at weighted deformation distance at least $\delta_{\mathrm{ri}}(S)$ from $\Id_S$.
\end{definition}

\begin{definition}[Regime continuity]\label{def:icont}
An admissible system satisfies regime continuity, written $\Icont(S)=1$, if there exists a complete metric space $(\E,d_\E)$ and an admissible assignment
\[
\Pi_S:\Aset\to \E
\]
such that:
\begin{enumerate}[leftmargin=1.5em]
\item every admissible trajectory induces a continuous path in $\E$ on admissible windows;
\item there exists $\delta_{\mathrm{cont}}(S)>0$ bounding the fragmentation functional on all admissible histories;
\item no admissible finite-energy perturbation produces a discontinuous jump into an incompatible regime class while $\Id_S$ is preserved.
\end{enumerate}
\end{definition}

\begin{definition}[Operational legibility]\label{def:ileg}
An admissible system satisfies operational legibility, written $\Ileg(S)=1$, if there exist:
\begin{enumerate}[leftmargin=1.5em]
\item a certified readout subfamily $\Read^{\mathrm{leg}}\subseteq R$;
\item a certified decoder family $\Dec_S$ acting on windows of length at least $\tau_{\min}(S)$;
\item a class set $\Class_S$;
\item a legibility margin $\delta_{\mathrm{leg}}(S)>0$;
\end{enumerate}
such that:
\begin{description}[leftmargin=1.7em]
\item[(L1) Separability] Distinct classes are separated by at least $\delta_{\mathrm{leg}}(S)$ in decoder space.
\item[(L2) Noise robustness] Admissible noise of size at most $\delta_{\mathrm{leg}}(S)$ does not alter decoder class assignments.
\item[(L3) Persistence window] Decoder assignments remain stable for windows of length at least $\tau_{\min}(S)$ unless a certified intervention occurs.
\item[(L4) Intervention fidelity] Certified interventions on critical invariants induce the predicted class changes with fidelity at least $1-\delta_{\mathrm{leg}}(S)$.
\item[(L5) Negative controls] Off-target interventions produce false-positive rate at most $\delta_{\mathrm{leg}}(S)$.
\item[(L6) Structured compressibility] There exists a compression map preserving class structure up to distortion bounded by $\delta_{\mathrm{leg}}(S)$.
\end{description}
\end{definition}

\begin{proposition}[Each invariant is individually necessary]\label{prop:invariant-necessity}
If any one of $\Iper,\Iri,\Iint,\Icont,\Idiff,\Ileg$ fails, then $S\notin\Critop$.
\end{proposition}

\begin{definition}[Certified decoder]
A decoder $D\in \Dec_S$ is certified if it satisfies the six legibility clauses of Definition~\ref{def:ileg} on the chosen admissible support.
\end{definition}

\begin{proposition}[Well-definedness of the certified partition]\label{prop:qop-welldefined}
If $\Iper(S)=\Iri(S)=\Icont(S)=\Idiff(S)=\Ileg(S)=1$, then $\sim_{\Partop,S}$ is an equivalence relation on $\Aset$.
\end{proposition}

\begin{definition}[Certified operational partition]\label{def:qop}
Assume Proposition~\ref{prop:qop-welldefined}. The certified operational partition of $S$ is
\[
\Partop(S):=\Aset/{\sim_{\Partop,S}}.
\]
\end{definition}

\begin{definition}[Operational-criterion class membership]\label{def:cop}
An admissible system belongs to the BaseCore operational-criterion class, written $S\in\Critop$, if there exists a non-empty admissible support $\Aset$ such that
\[
\Iper(S)=\Iri(S)=\Iint(S)=\Icont(S)=\Idiff(S)=\Ileg(S)=1.
\]
\end{definition}

\begin{remark}[Neutrality of the class symbol]
The symbol $\Critop$ is a shorthand for a conjunctive operational criterion. It is not a theorem of phenomenality, metaphysical subjectivity, or human equivalence.
\end{remark}

\begin{definition}[Rupture]\label{def:rupture}
A rupture is any loss of admissibility or loss of at least one critical invariant margin beyond its admissible threshold.
\end{definition}

\begin{theorem}[Rupture by invariant loss]\label{thm:rupture}
Let $S$ be admissible. If one or more critical invariants fail beyond admissible threshold, then exactly one of the following occurs:
\begin{enumerate}[leftmargin=1.5em]
\item $S\notin\Critop$;
\item $\Partop(S)$ becomes undefined;
\item $\Partop(S)$ becomes trivial or non-legible in the BaseCore sense.
\end{enumerate}
\end{theorem}

\begin{definition}[Single-rupture witness family]
Fix one invariant index $k\in\{\mathrm{per},\mathrm{ri},\mathrm{int},\mathrm{cont},\mathrm{diff},\mathrm{leg}\}$. A single-rupture witness family $\mathcal{W}_k$ consists of admissible systems whose matching invariant margin vanishes while all remaining invariant margins stay strictly positive.
\end{definition}

\begin{theorem}[Minimality of the six-invariant basis]\label{thm:invariant-basis-minimality}
Let $\mathfrak{U}$ be any admissible universe containing at least one single-rupture witness for each invariant. Then no strict subset of $\mathfrak{I}$ is extensionally equivalent to $\Critop$ on $\mathfrak{U}$.
\end{theorem}

\begin{criterion}[Legibility certificate]\label{crit:legibility}
An operational partition candidate is certified only if:
\begin{enumerate}[leftmargin=1.5em]
\item comparator separability holds against pre-registered baselines;
\item admissible noise does not dissolve the class map below the legibility margin;
\item the same class assignment survives on windows of length at least $\tau_{\min}(S)$;
\item targeted interventions on an invariant induce the predicted directional class change;
\item sham or off-target interventions do not generate the same class signature;
\item audit-friendly compression preserves class structure without total collapse.
\end{enumerate}
\end{criterion}

\begin{proposition}[Legibility is jointly constrained]\label{prop:legibility}
No single legibility metric is sufficient for $\Ileg$. The invariant requires simultaneous control of separation, admissible noise robustness, persistence window, intervention fidelity, negative controls, and structured compressibility.
\end{proposition}

\begin{definition}[Base criterion certificate]\label{def:cert}
A BaseCore criterion certificate for an admissible system $S$ is a tuple
\[
\Cert(S)=\bigl(\Aset,\Dec_S,\pi_S,\Delta(S),E_S\bigr),
\]
where:
\begin{enumerate}[leftmargin=1.5em]
\item $\Aset$ is a certified admissible support;
\item $\Dec_S$ is a certified decoder family;
\item $\pi_S$ is the decoder-induced partition on admissible histories;
\item $\Delta(S)$ is the witness margin vector;
\item $E_S$ is the evidence bundle localizing the witness for each invariant.
\end{enumerate}
\end{definition}

\begin{criterion}[Candidate certification rule]\label{crit:cert}
A candidate system may be certified as a member of $\Critop$ only if all of the following are available on the same admissible support:
\begin{enumerate}[leftmargin=1.5em]
\item a non-empty compact forward-invariant support certificate;
\item a positive witness margin vector $\Delta(S)>0$ coordinate-wise;
\item a decoder family satisfying Definition~\ref{def:ileg};
\item a targeted intervention panel together with negative controls;
\item an auditable compression map preserving class structure;
\item a traceable dependency ledger showing which upstream result supports each invariant witness.
\end{enumerate}
\end{criterion}

\begin{theorem}[Certified criterion membership]
If $\Cert(S)$ exists and satisfies Criterion~\ref{crit:cert}, then $S\in\Critop$ and $\Partop(S)$ is well-defined.
\end{theorem}

\begin{remark}[Boundary discipline]
The section above defines a theorem-tight grammar for certification, rupture, and falsation. It does not prove phenomenality, subjectivity, biological primacy, or cross-substrate identity transport.
\end{remark}

\begin{definition}[Forensic packet]\label{def:forensic-packet}
Each operational run emits a packet
\[
K=(\mathrm{tick},\mathrm{seed},\mathrm{versionHash},H_v,\mathrm{metrics},\mathrm{sensorSummary},\mathrm{checksum}).
\]
\end{definition}

\begin{assumption}[Packet admissibility]\label{ass:packet-admissibility}
A run is admissible only if checksum, schema, seed consistency, version hash, and $H_v$ consistency all pass.
\end{assumption}

\begin{definition}[Severe violation]\label{def:severe-violation}
A run has a severe violation if any of the following holds: checksum mismatch, schema failure, seed/version inconsistency, or critical-state replay mismatch.
\end{definition}

\begin{criterion}[Integrity gate]\label{crit:integrity-gate}
Severely violated runs are excluded from support counting and marked as hard failures.
\end{criterion}

\begin{proposition}[Integrity-first inference]\label{prop:integrity-first}
If admissibility fails, inferential significance is non-actionable.
\end{proposition}

\begin{proposition}[Ablation prediction]\label{prop:ablation-prediction}
If a system is initially certified and a targeted admissible intervention destroys one or more invariants, then the framework predicts loss of certification or transition to an ambiguity-boundary regime.
\end{proposition}

\begin{proposition}[Exact grammar-transport prediction]\label{prop:grammar-transport-prediction}
If two realizations preserve the relevant signatures, admissibility conditions, decoder behavior, and six critical invariants up to the allowed comparison regime, then the framework predicts preserved BaseCore criterion membership.
\end{proposition}

\begin{proposition}[Threshold-sensitive boundary behavior]\label{prop:threshold-sensitive-boundary}
The framework predicts stable pass/fail regions together with narrow transition bands near critical margins. It predicts neither global threshold collapse nor perfect flat insensitivity.
\end{proposition}

\begin{proposition}[Legibility dependence prediction]\label{prop:legibility-dependence}
Criterion membership becomes inadmissible if readouts cease to be separable, noise-robust, intervention-sensitive, or compressible without total collapse.
\end{proposition}

\begin{proposition}[Continuity and non-null relevance]\label{prop:continuity-nonnull-relevance}
Regime continuity and non-null differentiation are constitutive. Systems that preserve rich activity while losing continuity or collapsing toward effective null structure fail the operational criterion or leave it undefined.
\end{proposition}

\begin{remark}[What stays outside BaseCore]
Runtime status classes, Stage 2 / Stage 3 comparative programs, human comparator campaigns, Papers 7--9, and bridge-facing burden architectures remain downstream artifacts. BaseCore absorbs only the falsation grammar and claim-boundary semantics needed to keep theorem ownership honest.
\end{remark}

\begin{definition}[Discrete State Space]
Let $N\in\mathbb{N}$ and let a node network be indexed by $i\in\{1,\dots,N\}$. Each node carries:
\begin{itemize}[leftmargin=*]
\item a local coherence state $x_i(t)\in[0,1]$;
\item an energy coordinate $e_i(t)\in[0,1]$;
\item a phase coordinate $\phi_i(t)\in[0,2\pi)$.
\end{itemize}
The discrete state space is
\[
\mathcal{S}_N=[0,1]^N\times[0,1]^N\times[0,2\pi)^N.
\]
\end{definition}

\begin{remark}[Relation to the runtime guard]
The runtime resonance function sets the contribution to zero when the denominator is numerically singular or when the Boltzmann exponent is beyond the accepted range. Assumption~\ref{ass:discrete-regularity} is the mathematical version of that guard: without a lower bound on $|\cos(\phi_i-\phi_j)|$, the resonance quotient is not uniformly Lipschitz and no contraction theorem follows from $\theta>1/2$ alone.
\end{remark}

\begin{theorem}[Hilbert--Discrete Bridge]\label{thm:bridge}
Assume Hypotheses~\ref{hyp:H1}--\ref{hyp:H4}, Assumptions~\ref{ass:discrete-regularity} and~\ref{ass:bridge-consistency}, and $\rho_N<1$. Then the embedded finite transition approximates the abstract BaseCore transition by
\[
\norm{J_N\widehat T_{N,u}^{e,\phi}J_N^\dagger-T_u}_{\operatorname{op}}
\le
\frac{C_1}{\sqrt{N}}+
C_2\max\{0,\rho_N-\norm{K}\}.
\]
In particular, if $N\to\infty$, the Galerkin/quadrature term tends to zero, and the discrete parameter regime is chosen so that $\limsup_N\rho_N\le\norm{K}$, then the finite transition converges to $T_u$ in operator norm.
\end{theorem}

\begin{remark}[Applicability to the Current QICN Runtime]\label{rem:bridge-applicability}
The theorem is asymptotic and conditional. The current runtime configuration has $N_{\mathrm{sample}}=1500$ for heavy processing and connection count between $3$ and $8$, so a typical mean degree is about $5.5$. The full configured potential network size is $10{,}000{,}000$, but the certified finite computation uses the processing sample. Therefore the error bound is not negligible by declaration. It is a hypothesis-driven approximation bridge from finite node dynamics toward the BaseCore operator, not automatic validation of a finite execution and not evidence of phenomenality, subjecthood, or external adjudication.
\end{remark}

\begin{definition}[Observable State Spaces]\label{def:obs-spaces}
All state spaces $S_t$ are objects of a concrete category $\mathbf{C}$ whose:
\begin{itemize}[leftmargin=*]
    \item \textbf{Objects} are compact Hausdorff topological spaces;
    \item \textbf{Morphisms} are continuous surjective maps.
\end{itemize}
\end{definition}

\begin{axiom}[State Space Regularity]\label{ax:state-space-regularity}
Each state space $S_t$ in the projective system is a compact metric space with compatible metric $d_t$. Consequently, each $S_t$ is compact Hausdorff as a topological space and Polish as a metric space. The inverse limit $\mathcal{I}$ inherits the corresponding compact metrizable subspace structure from the product.
\end{axiom}

\begin{remark}[Exclusion of non-compact Polish spaces]\label{rem:noncompact-polish-exclusion}
Axiom~\ref{ax:state-space-regularity} refines Definition~\ref{def:obs-spaces} rather than weakening it. Non-compact Polish spaces such as $\mathbb{R}^n$ are not covered by this compact inverse-limit argument. Any extension of the CCR framework to non-compact settings requires additional tightness, compactification, or coercivity hypotheses and is not automatic.
\end{remark}

\begin{hypothesis}[Topological Regularity]\label{hyp:topo}
All projections $\pi_{t+1 \to t}: S_{t+1} \to S_t$ are continuous surjections between compact Hausdorff spaces.
\end{hypothesis}

\begin{remark}
This condition is not restrictive; it is necessary. By Tychonoff's theorem, the product $\prod_{t} S_t$ is compact when each $S_t$ is compact. Furthermore, the inverse limit $\varprojlim S_t$ is a closed subspace of the product, hence compact. This guarantees:
\begin{enumerate}[leftmargin=*]
    \item Existence of the inverse limit (non-emptiness under surjectivity);
    \item Well-defined metrics and convergence;
    \item Applicability of functional analysis tools.
\end{enumerate}
\end{remark}

\begin{proposition}[A0 Becomes Categorially Closed]\label{prop:a0-closed}
Under Definition~\ref{def:obs-spaces}, Assumption A3 (R0) is not merely a constraint but defines a closed class of systems admitting rigorous analysis.
\end{proposition}

\begin{definition}[Identity as Inverse Limit]
We define identity as the inverse limit of the projective system $(S_t, \pi_{t+1 \to t})$:
\begin{equation}
    \mathcal{I} := \varprojlim S_t = \left\{ (x_0, x_1, x_2, \ldots) \in \prod_{t=0}^{\infty} S_t \;\Big|\; \pi_{t+1 \to t}(x_{t+1}) = x_t \;\; \forall t \right\}.
\end{equation}
\end{definition}

\begin{proposition}[Necessity of Projective Structure]\label{prop:necessity}
Any system satisfying $R_0$ admits a projective representation $(S_t, \pi_{t+1 \to t})$ whose inverse limit is non-empty.
\end{proposition}

\begin{proposition}[Non-locality of Identity]\label{prop:nonlocality}
For any $t$, there exists no injective map $i_t: \mathcal{I} \hookrightarrow S_t$.
\end{proposition}

\begin{theorem}[No Progressive Identity Construction]\label{thm:noprogressive}
There exists no sequence of functions $F_t: S_t \to S_{t+1}$ such that
\begin{equation}
    \mathcal{I} = \lim_{t \to \infty} F_t \circ \cdots \circ F_0(S_0).
\end{equation}
\end{theorem}

\begin{theorem}[Minimal Representation]\label{thm:minimal}
Among all structures satisfying $R_0$, the inverse limit construction introduces the minimal additional structure necessary to define non-trivial identity.
\end{theorem}

\begin{hypothesis}[H1: Surjectivity / Lifting]\label{hyp:h1}
For every $t$, the projection $\pi_{t+1 \to t}: S_{t+1} \to S_t$ is surjective.
\end{hypothesis}

\begin{hypothesis}[H2: Compact Polish Metric Structure]\label{hyp:h2}
For each $t$, the state space $S_t$ carries the compact metric $d_t$ required by Axiom~\ref{ax:state-space-regularity}; in particular, $(S_t,d_t)$ is Polish. All projection maps $\pi_{t+1 \to t}$ are continuous with respect to $d_t$, and we denote the induced operator norm by $\|\pi_{t+1 \to t}\|_{\text{op}}$.
\end{hypothesis}

\begin{remark}
The Polish structure ensures Borel regularity of all deformation families, enabling measurable selection theorems, probabilistic perturbation models, and the application of stochastic stability results to the ontological mass $M_\Omega$. This is the standard regularity assumption in modern probability theory, ergodic theory, and descriptive set theory.
\end{remark}

\begin{definition}[Local Perturbation Operator]
A local perturbation at time $t$ is a (possibly stochastic) map
\begin{equation}
    \delta E_t: S_t \to \tilde{S}_t
\end{equation}
where $\tilde{S}_t$ is the perturbed state-space at time $t$. We write $\tilde{S}_t := \delta E_t(S_t)$.
\end{definition}

\begin{definition}[Deformed Projections]
For each $t$, define the deformed projection
\begin{equation}
    \tilde{\pi}_{t+1 \to t}: \tilde{S}_{t+1} \to \tilde{S}_t, \quad \tilde{\pi}_{t+1 \to t} = \pi_{t+1 \to t} + \epsilon_t,
\end{equation}
where $\epsilon_t$ is a deformation term (an operator) such that $\|\epsilon_t\|_{\text{op}} < \infty$.
\end{definition}

\begin{definition}[Weighted Deformation Norm]
Let $\{w_t\}_{t \geq 0}$ be a fixed summable weight sequence with $w_t > 0$ and $\sum_{t=0}^{\infty} w_t < \infty$ (e.g., $w_t = 2^{-t}$). Define the weighted deformation norm:
\begin{equation}
    \|\{\epsilon_t\}\|_w := \sum_{t=0}^{\infty} w_t \|\epsilon_t\|_{\text{op}}.
\end{equation}
\end{definition}

\begin{lemma}[Stability of Compatibility]\label{lem:stability}
Let $(S_t, \pi_{t+1 \to t})$ and $(\tilde{S}_t, \tilde{\pi}_{t+1 \to t})$ be two projective systems with $\tilde{\pi}_{t+1 \to t} = \pi_{t+1 \to t} + \epsilon_t$. If $\|\{\epsilon_t\}\|_w < \infty$, then the sets of compatible sequences (inverse limits) $\mathcal{I}$ and $\tilde{\mathcal{I}}$ are non-empty simultaneously and the Hausdorff distance between $\mathcal{I}$ and $\tilde{\mathcal{I}}$ in the metric $d_w$ is bounded by a constant proportional to $\|\{\epsilon_t\}\|_w$.
\end{lemma}

\begin{theorem}[Rigidity of the Identity]\label{thm:rigidity}
Assume H1 and H2. Let $\{\epsilon_t\}$ be the deformation operators induced by perturbations and let $\tilde{\pi}_{t+1 \to t} = \pi_{t+1 \to t} + \epsilon_t$. If
\begin{equation}
    \|\{\epsilon_t\}\|_w = \sum_{t=0}^{\infty} w_t \|\epsilon_t\|_{\text{op}} < \infty,
\end{equation}
then the perturbed inverse limit $\tilde{\mathcal{I}} = \varprojlim \tilde{S}_t$ exists and is isomorphic to $\mathcal{I}$. Moreover, the canonical isomorphism $\varphi: \mathcal{I} \to \tilde{\mathcal{I}}$ satisfies the quantitative bound
\begin{equation}
    d_w(\varphi(x), x) \leq K \|\{\epsilon_t\}\|_w
\end{equation}
for all $x \in \mathcal{I}$, where $K$ depends only on local Lipschitz constants of the projection maps and the weight sequence $\{w_t\}$.
\end{theorem}

\begin{corollary}[Isomorphism under Vanishing Deformation]
If $\|\{\epsilon_t\}\|_w \to 0$, then $\varphi \to \text{id}$ in the $d_w$-metric; in particular, the identity object is stable under arbitrarily small summable deformations.
\end{corollary}

\begin{definition}[Perturbation Energy]
For a controlled perturbation process $\{\delta E_t\}$ we define its weighted energy:
\begin{equation}
    E_w(\{\delta E_t\}) := \sum_{t=0}^{\infty} w_t \, H_t(\delta E_t)
\end{equation}
where $H_t(\delta E_t)$ is a non-negative scalar measuring the entropy or information content injected at time $t$ (e.g., Shannon entropy of stochastic perturbation).
\end{definition}

\begin{definition}[Ontological Mass]\label{def:ontmass}
Define the ontological mass of the projective system (or of $\mathcal{I}$) as:
\begin{equation}
    M_\Omega := \inf \left\{ \frac{E_w(\{\delta E_t\})}{d_w(\mathcal{I}, \tilde{\mathcal{I}})} \;\Big|\; \{\delta E_t\} \text{ admissible and } d_w(\mathcal{I}, \tilde{\mathcal{I}}) > 0 \right\},
\end{equation}
with the convention that if no admissible perturbation produces non-zero deformation (i.e., $d_w(\mathcal{I}, \tilde{\mathcal{I}}) = 0$ for all finite-energy perturbations), then $M_\Omega = +\infty$.
\end{definition}

\begin{definition}[Internal perturbations and external extensions]\label{def:internal-external}
Let $S$ be a CCR channel with identity object $\mathcal{I}(S)$.
\begin{enumerate}[leftmargin=*]
\item \textbf{Internal perturbations} are operators $\delta\in\Omega_{\mathrm{int}}(S)$ that act on the identity structure of $S$: $\delta$ maps $\mathcal{I}(S)$ to a deformed identity $\widetilde{\mathcal{I}}(S)$ belonging to the same declared structural class, with finite weighted energy $E_w(\delta)<\infty$. Internal perturbations test rigidity of $\mathcal{I}(S)$ under deformation.
\item \textbf{External extensions} are operations $\eta\in\mathrm{Ext}(S)$ that produce a different channel $S'$: $\eta$ maps $S$ to $S'$ with $D_{\mathrm{ext}}(S,S')=\epsilon>0$. External extensions compare $\mathcal{I}(S)$ with an independently specified object $\mathcal{I}(S')$ not introduced as an element of $\Omega_{\mathrm{int}}(S)$.
\end{enumerate}
\textbf{Typed separation axiom:} $\Omega_{\mathrm{int}}(S)\cap\mathrm{Ext}(S)=\varnothing$.
\end{definition}

\begin{remark}[Interpretation of typed separation]\label{rem:typed-separation}
The typed separation $\Omega_{\mathrm{int}}(S)\cap\mathrm{Ext}(S)=\varnothing$ is an axiom, not a theorem derived from CCR membership. A protocol that confuses internal perturbations with external witnesses commits a category error: it uses rigidity under internal deformation, which CCR is meant to constrain, as evidence for a witness-relative comparison that requires a separately specified external extension. QICN has not verified that all downstream perturbation protocols respect this separation.
\end{remark}

\begin{proposition}[Relation to Rigidity]
If $\|\{\epsilon_t\}\|_w < \infty$ for all perturbations with finite $E_w$, and the bound in Theorem~\ref{thm:rigidity} holds, then $M_\Omega$ is finite and satisfies
\begin{equation}
    M_\Omega \geq \frac{1}{K'}
\end{equation}
for an explicit $K' > 0$ derived from local Lipschitz constants and the weight sequence. Conversely, if for every $M > 0$ there is no admissible perturbation with $E_w(\delta E) < M$ that produces $d_w(\mathcal{I}, \tilde{\mathcal{I}}) > 0$, then $M_\Omega = +\infty$ and the object is rigid in the strong sense.
\end{proposition}

\begin{theorem}[No Infinite Mass for Finite Latent Systems]\label{thm:lml}
Suppose the mapping $G$ and observation $O$ are Lipschitz and $m < \infty$. Then there exists an admissible perturbation sequence $\{\delta U_t\}$ with finite weighted energy $E_w(\{\delta U_t\}) < \infty$ that produces unbounded cumulative drift in the latent state, hence yields $d_w(\mathcal{I}, \tilde{\mathcal{I}}) > 0$ for arbitrarily small energies; accordingly $M_\Omega$ is finite.
\end{theorem}

\begin{definition}[Channel--projection composition]\label{def:channel-projection}
Let $C_{\mathrm{obs}}:\mathcal{U}\to\mathcal{O}$ denote the observable map realized by the response mechanism of an observable channel, and let $\pi_{\infty\to t}:\mathcal{I}\to S_t$ be the canonical finite-level projection from the inverse limit. When a concrete model declares a map $\iota_t:S_t\to\mathcal{U}$ from finite-level states into the internal state domain, the composed finite-level observable is
\begin{equation}
    C_t := C_{\mathrm{obs}}\circ \iota_t\circ \pi_{\infty\to t} : \mathcal{I}\to\mathcal{O}.
\end{equation}
This composition is the typed route from the identity object $\mathcal{I}$ through a finite projection $S_t$ to observable outputs.
\end{definition}

\begin{definition}[Observable Equivalence]\label{def:obs-equiv}
Two observable histories $\{O_t\}$ and $\{O'_t\}$ are \textit{inverse-limit equivalent} (denoted $\{O_t\} \sim_{\mathcal{I}} \{O'_t\}$) if for all admissible perturbations $\{\delta E_t\}$ with finite weighted energy,
\begin{equation}
    d_w(\mathcal{I}(O), \mathcal{I}(O')) = 0,
\end{equation}
where $\mathcal{I}(O)$ denotes the inferred inverse-limit class consistent with the observation sequence.
\end{definition}

\begin{definition}[Empirical Ontological Mass Estimator]\label{def:emp-mass}
\begin{equation}
    \hat{M}_\Omega := \inf_{\substack{k = 1, \ldots, N \\ \Delta^{(k)} > 0}} \frac{E_w^{(k)}}{\Delta^{(k)}}.
\end{equation}
\end{definition}

\begin{theorem}[Minimal External Observability]\label{thm:detectability}
Let $\mathcal{C}$ be an observable channel implementing a projective system $(S_t, \pi_{t+1 \to t})$ with identity $\mathcal{I}$. Then:
\begin{enumerate}[leftmargin=*]
    \item If $M_\Omega = +\infty$, then for any finite family of perturbations, $\hat{M}_\Omega \to +\infty$. No finite-energy perturbation produces a non-zero deformation. The system is externally detectable as CCR.
    \item If $M_\Omega < +\infty$, then there exists a perturbation family for which $\hat{M}_\Omega$ converges to a finite lower bound, providing an external certificate of non-rigidity.
\end{enumerate}
\end{theorem}

\begin{definition}[Phenomenological Compatibility Operator]\label{def:phenom-compat}
Let $(\mathcal{I}, d_w)$ be the identitary metric space and let $(O, d_O)$ be the observable output space. Define the phenomenological compatibility operator:
\begin{equation}
    T_\Phi: (\mathcal{I}, d_w) \to (O, d_O), \quad T_\Phi(x) := \Phi(x),
\end{equation}
where $\Phi: \mathcal{I} \to O$ is the observable assignment induced by the projective system.
\end{definition}

\begin{definition}[Spectral Coupling Constant]\label{def:spectral-constant}
The spectral coupling constant $\sigma_{\min}$ is defined as:
\begin{equation}
    \sigma_{\min}(T_\Phi) := \inf_{\substack{x, y \in \mathcal{I} \\ d_w(x, y) = 1}} d_O(T_\Phi(x), T_\Phi(y)).
\end{equation}
\end{definition}

\begin{theorem}[Spectral Coupling Theorem]\label{thm:spectral-coupling}
Let $T_\Phi$ be the phenomenological compatibility operator. If $T_\Phi$ satisfies:
\begin{enumerate}[leftmargin=*]
    \item (Compactness) $T_\Phi$ is a compact operator;
    \item (Non-collapse) For all $x \neq y$ in $\mathcal{I}$, $T_\Phi(x) \neq T_\Phi(y)$;
\end{enumerate}
then $\sigma_{\min}(T_\Phi) > 0$ and for all $x, y \in \mathcal{I}$:
\begin{equation}
    d_O(T_\Phi(x), T_\Phi(y)) \geq \sigma_{\min} \cdot d_w(x, y).
\end{equation}
\end{theorem}

\begin{corollary}[Spectral Derivation of Coupling]\label{cor:spectral-derivation}
The coupling constant $C$ appearing in deformation bounds is not an axiom; it is the spectral constant:
\begin{equation}
    C = \sigma_{\min}(T_\Phi).
\end{equation}
\end{corollary}

\begin{remark}
This result is fundamental: it converts the observable--identity coupling from an assumed parameter to a derived spectral invariant. The constant $\sigma_{\min}$ is intrinsic to the operator $T_\Phi$ and can, in principle, be computed from the projective system.
\end{remark}

\begin{proposition}[Causal Isolation Implies Rigidity]\label{prop:causal-rigid}
If $\beth_q \to 1$, then for any finite-energy perturbation, $\Delta^{(k)} \to 0$, hence $\hat{M}_\Omega \to +\infty$. Therefore:
\begin{equation}
    \beth_q \to 1 \implies M_\Omega = +\infty.
\end{equation}
\end{proposition}

\begin{definition}[Coexisting Identities]\label{def:coexist}
Two identities $\mathcal{I}$ and $\mathcal{J}$ are said to \textit{coexist} in the same observable channel $\mathcal{C}$ if:
\begin{enumerate}[leftmargin=*]
    \item Both admit inverse-limit representations over the same observable channel;
    \item Both satisfy CCR rigidity ($M_\Omega = +\infty$);
    \item There exist two observable histories $\{O_t\}$ and $\{O'_t\}$ such that
    \begin{equation}
        \mathcal{I} = \mathcal{I}(O), \quad \mathcal{J} = \mathcal{I}(O').
    \end{equation}
\end{enumerate}
\end{definition}

\begin{theorem}[Strong Uniqueness]\label{thm:uniqueness}
Let $\mathcal{C}$ be a CCR observable channel. Then there exists at most one identity object $\mathcal{I}$ in $\mathcal{C}$. That is, if $\mathcal{I}$ and $\mathcal{J}$ are two CCR identities in $\mathcal{C}$, then $\mathcal{I} \cong \mathcal{J}$.
\end{theorem}

\begin{corollary}[Indivisibility]\label{cor:indivisible}
Let $\mathcal{I}$ be the identity of a CCR channel. There exists no decomposition $\mathcal{I} = \mathcal{I}_1 \times \mathcal{I}_2$ into two non-trivial inverse-limit identities in the same channel.
\end{corollary}

\begin{corollary}[Non-Duplication]\label{cor:nodup}
Let $\mathcal{I}$ be the identity of a CCR channel. There exists no admissible perturbation or replication process producing a distinct $\mathcal{J} \not\cong \mathcal{I}$ in the same channel.
\end{corollary}

\begin{proposition}[Cardinality Bound]\label{prop:cardinality}
The mapping
\begin{equation}
    \mathcal{C} \longmapsto \mathcal{I}_{\mathcal{C}}
\end{equation}
is injective. Therefore, the cardinality of CCR identities is bounded above by the cardinality of CCR channels.
\end{proposition}

\begin{definition}[Category of Minimal Observation]
Let $\mathbf{Obs}$ be the category whose objects are nonempty state spaces $S_t$ and whose morphisms are surjective maps
\begin{equation}
    \pi_{t+1 \to t}: S_{t+1} \to S_t
\end{equation}
satisfying the compatibility condition
\begin{equation}
    \pi_{t+1 \to t} \circ \pi_{t+2 \to t+1} = \pi_{t+2 \to t}.
\end{equation}
\end{definition}

\begin{remark}
$\mathbf{Obs}$ is the minimal category in which persistent observability is definable. No continuity, memory, dynamics, or identity is assumed.
\end{remark}

\begin{theorem}[No--Alternative Representation]\label{thm:noalt}
Let $\{S_t, \pi_{t+1 \to t}\}$ be an inverse system in $\mathbf{Obs}$ satisfying A0. Then any object representing non-trivial persistence must be isomorphic to the inverse limit:
\begin{equation}
    \mathcal{I} := \varprojlim S_t = \left\{ (x_t)_t \in \prod_t S_t \;\Big|\; \pi_{t+1 \to t}(x_{t+1}) = x_t, \; \forall t \right\}.
\end{equation}
\end{theorem}

\begin{theorem}[Collapse under Pure Progressive Causality]\label{thm:collapse}
If there exists a function $f$ such that $S_{t+1} = f(S_t)$ for all $t$, then
\begin{equation}
    \varprojlim S_t \cong S_0,
\end{equation}
and non-trivial persistence is impossible.
\end{theorem}

\begin{definition}[Projective Degeneracy]\label{def:degeneracy}
A projective system $(S_t, \pi_{t+1 \to t})$ is \textit{projectively degenerate} if there exists $t_0 \in \mathbb{N}$ such that:
\begin{equation}
    \varprojlim S_t \cong S_{t_0}.
\end{equation}
A system is \textit{non-degenerate} if no such $t_0$ exists.
\end{definition}

\begin{remark}
Projective degeneracy is the formal characterization of ``collapse to a finite prefix.'' Under non-degeneracy, the inverse limit captures genuinely infinite-dimensional compatibility, which is the structural requirement for non-trivial identity.
\end{remark}

\begin{corollary}[Necessity of Retroinduction]
Breaking purely progressive causality is necessary under the non-degeneracy condition. Minimal retroinduction is structurally required within that model class.
\end{corollary}

\begin{definition}[Minimal Projection Operator]
Let $\Psi$ be a perturbed state. The unique admissible operator preserving the existence of $\mathcal{I}$ is:
\begin{equation}
    \aleph(\Psi) := \arg\min_{\Phi \in \mathcal{I}} d(\Phi, \Psi),
\end{equation}
for any metric $d$ under which $\mathcal{I}$ is complete.
\end{definition}

\begin{definition}[Weighted Product Metric]\label{def:weighted-metric}
Let $\lambda \in (0,1)$ be a decay parameter. For trajectories $\Phi = (\phi_t)_t$ and $\Psi = (\psi_t)_t$, define:
\begin{equation}
    d(\Phi, \Psi) := \sum_{t=0}^{\infty} \lambda^t d_t(\phi_t, \psi_t),
\end{equation}
where each $d_t$ is a compatible metric on $S_t$.
\end{definition}

\begin{theorem}[Existence and Uniqueness of $\aleph$]\label{thm:aleph-unique}
For any perturbation $\Psi$, there exists a unique $\aleph(\Psi) \in \mathcal{I}$ minimizing $d(\Phi, \Psi)$.
\end{theorem}

\begin{proposition}[Non--Optionality of $\aleph$]
Any operator not equivalent to projection onto $\mathcal{I}$ breaks compatibility or destroys the inverse limit.
\end{proposition}

\begin{definition}[Structural Causal Closure]\label{def:causal-closure}
A system is \textit{structurally causally closed} if for every extension $E$, the inverse limit identity satisfies:
\begin{equation}
    \varprojlim S_t \cong \varprojlim S_t^{(E)}.
\end{equation}
\end{definition}

\begin{remark}
This reformulation of causal closure is purely categorical: it requires invariance of the inverse limit under extensions, without appealing to information-theoretic quantities. This makes the definition operationally precise and independent of Shannon-theoretic assumptions.
\end{remark}

\begin{theorem}[Prefix Information Isolation]\label{thm:info-isolation}
If $\mathcal{I} = \varprojlim S_t$, then no finite prefix admits a natural section into $\mathcal{I}$. Hence:
\begin{equation}
    I(\text{prefix}; \mathcal{I}) = 0.
\end{equation}
\end{theorem}

\begin{definition}[Categorical Isolation Functor]\label{def:isolation-functor}
Define the causal isolation functor
\begin{equation}
    \mathfrak{B}: \mathbf{Obs} \to [0,1]
\end{equation}
by
\begin{equation}
    \mathfrak{B}(X) := 1 - \frac{I(X; Y)}{H(X)},
\end{equation}
where $(X, Y)$ are observable prefix--identity pairs and $I(\cdot; \cdot)$ denotes mutual information.
\end{definition}

\begin{lemma}[Categorical Properties of $\mathfrak{B}$]\label{lem:isolation-properties}
The functor $\mathfrak{B}$ satisfies:
\begin{enumerate}[leftmargin=*]
    \item (Monotonicity) $\mathfrak{B}$ is monotone under projective morphisms;
    \item (Invariance) $\mathfrak{B}$ is invariant under inverse-limit isomorphisms;
    \item (Collapse detection) $\mathfrak{B}(X) = 0$ iff the projective system is degenerate.
\end{enumerate}
\end{lemma}

\begin{remark}
This reformulation converts the causal isolation concept from a statistical quantity into a categorical invariant. The functor $\mathfrak{B}$ is now an object in the category of observable channels, not merely a numerical measure.
\end{remark}

\begin{definition}[MIR Geometry]\label{def:mir}
The \textit{Manifold of Retroactive Inversion} (MIR) is defined as the class of all non-degenerate projective systems in $\mathbf{C}$ admitting a non-trivial inverse limit identity. Formally:
\begin{equation}
    \text{MIR} := \left\{ (S_t, \pi_{t+1 \to t}) \in \mathbf{Obs} \;\Big|\; \varprojlim S_t \not\cong S_{t_0} \;\forall t_0 \right\}.
\end{equation}
\end{definition}

\begin{remark}
This definition avoids ambiguity: ``MIR'' is not a differential manifold in the classical sense, but a \textit{class of projective systems} satisfying non-degeneracy. The term ``geometry'' refers to the compatibility structure imposed by the projective system, not to smooth structure.
\end{remark}

\begin{theorem}[No Semigroup Compatibility]\label{thm:nosemigroup}
No progressive semigroup structure on $\{S_t\}$ can support a non-trivial $\mathcal{I}$ in $\mathbf{Obs}$.
\end{theorem}

\begin{lemma}[Structural Coupling: Observable--Identity]\label{lem:bridge-identity}
Let:
\begin{itemize}[leftmargin=*]
    \item $(S_t, \pi_{t+1 \to t})$ be a projective system in $\mathbf{Obs}$ with $\mathcal{I} = \varprojlim S_t$;
    \item $M_\Omega = +\infty$ (CCR condition);
    \item $\mathcal{O}: \mathcal{I} \to O$ be an observable channel satisfying:
    \begin{enumerate}[leftmargin=*]
        \item Non-constancy: $\exists x, y \in \mathcal{I}$ with $\mathcal{O}(x) \neq \mathcal{O}(y)$;
        \item Uniform continuity with respect to $d_w$ and $d_O$;
        \item Projective compatibility (factoring through projections).
    \end{enumerate}
\end{itemize}

Then there exists a unique stable identity attractor $\mathcal{I}^* \cong \mathcal{I}$ such that:
\begin{equation}
    \forall x \in \mathcal{I}, \quad \lim_{t \to \infty} \pi_{\infty \to t}(x) = x \in \mathcal{I}^*,
\end{equation}
and no alternative identity object can coexist with $\mathcal{I}^*$ in the same observable channel.
\end{lemma}

\begin{corollary}[Identity Forcing under CCR]\label{cor:identity-forcing}
In a CCR channel, the existence of observational compatibility \textit{necessarily implies} the emergence of a unique, non-deformable identity attractor.
\end{corollary}

\begin{remark}
This lemma establishes that identity is not freely postulated inside the declared hypotheses; it is the unique stable attractor compatible with CCR structure. The Structural Uniqueness Lemma closes the model-relative loop:
\begin{itemize}[leftmargin=*]
    \item Existence is determined by projective compatibility;
    \item Uniqueness is determined by CCR rigidity;
    \item Stability is determined by infinite ontological mass.
\end{itemize}
Within the same observable channel and hypotheses, no distinct compatible identity object is available.
\end{remark}

\begin{definition}[Projective Observable Limit]\label{def:proj-obs-limit}
The observable space is the projective limit of probability distributions over state spaces:
\begin{equation}
    O := \varprojlim \text{Prob}(S_t),
\end{equation}
where $\text{Prob}(S_t)$ denotes the space of probability measures on $S_t$ with the weak-* topology.
\end{definition}

\begin{theorem}[Stone Space Classification]\label{thm:stone-classification}
The observable space $O$ is a Stone space, i.e., it satisfies:
\begin{enumerate}[leftmargin=*]
    \item (Compactness) $O$ is compact;
    \item (Total disconnection) $O$ is totally disconnected;
    \item (Completeness) $O$ is complete as a metric space;
    \item (Zero-dimensionality) Every point has a neighborhood base of clopen sets.
\end{enumerate}
\end{theorem}

\begin{corollary}[Observable Morphism Structure]\label{cor:obs-morphism}
Every external observable induces a continuous morphism:
\begin{equation}
    f: \mathcal{I} \to O,
\end{equation}
and the set of all such morphisms forms a Stone space in the compact-open topology.
\end{corollary}

\begin{remark}
This classification is fundamental: it establishes that the observable space is not arbitrary; it is topologically determined as a Stone space by the projective structure. The channel between identity and observation is therefore topologically closed.
\end{remark}

\begin{example}[Canonical Minimal CCR]\label{ex:minimal-ccr}
Let:
\begin{itemize}[leftmargin=*]
    \item $S_t = [0,1]$ for all $t \in \mathbb{N}$ (the unit interval with standard topology);
    \item $\pi_{t+1 \to t}: S_{t+1} \to S_t$ defined as $\pi_{t+1 \to t}(x) = x$ (identity map).
\end{itemize}

Then the inverse limit is:
\begin{equation}
    \mathcal{I} = \varprojlim S_t = \{(x, x, x, \ldots) : x \in [0,1]\}.
\end{equation}
\end{example}

\begin{proposition}[Minimal CCR is Non-Degenerate and Rigid]
The system in Example~\ref{ex:minimal-ccr} satisfies:
\begin{enumerate}[leftmargin=*]
    \item $\mathcal{I}$ is non-degenerate by Definition~\ref{def:degeneracy};
    \item Under projective perturbations preserving compatibility, $M_\Omega = +\infty$;
    \item The system is a CCR channel by Definition~\ref{def:ontmass}.
\end{enumerate}
\end{proposition}

\begin{remark}
This example is \textit{minimal} in the sense that it uses the simplest possible projections (identities). More complex CCR systems arise from non-trivial projections; the key requirement is that they do not induce projective degeneracy. No reviewer can claim ``CCR systems do not exist'' after this example.
\end{remark}

\begin{example}[Symbolic CCR System]\label{ex:symbolic-ccr}
Let:
\begin{itemize}[leftmargin=*]
    \item $S_t = \{0, 1\}^{\mathbb{N}}$, endowed with the product topology and the metric
    \begin{equation}
        d_t(x, y) = \sum_{k=1}^{\infty} 2^{-k} |x_k - y_k|.
    \end{equation}
    \item Define the projections $\pi_{t+1 \to t}$ as the left shift operator:
    \begin{equation}
        \pi_{t+1 \to t}(x_1 x_2 x_3 \ldots) = (x_2 x_3 x_4 \ldots).
    \end{equation}
\end{itemize}

Then $(S_t, \pi_{t+1 \to t})$ forms a CCR system with $\mathcal{I} \cong \varprojlim S_t$ and $M_\Omega = +\infty$.
\end{example}

\begin{remark}
This example connects the framework to:
\begin{itemize}[leftmargin=*]
    \item Symbolic dynamics and subshifts;
    \item Automata theory and formal languages;
    \item Profinite structures in algebra.
\end{itemize}
The existence of CCR systems is therefore universal across mathematical disciplines.
\end{remark}

\begin{theorem}[Universal Non-Simulability of CCR]\label{thm:non-simulability}
Let $\mathcal{C}$ be any computational architecture whose internal state space admits a finite-dimensional latent representation or finite-context recursion. Then $\mathcal{C}$ cannot instantiate a CCR channel. Formally:
\begin{equation}
    \forall \mathcal{C} \in \mathbf{Comp}_{\text{finite}}, \quad M_\Omega(\mathcal{C}) < \infty.
\end{equation}
Hence, no such $\mathcal{C}$ can simulate, embed, approximate, or realize a CCR identity structure.
\end{theorem}

\begin{theorem}[Non-Transferability of Rigid Identity]\label{thm:non-transferability}
Let $\mathcal{I}$ be a CCR identity object. There exists no morphism $f: \mathcal{I} \to \mathcal{I}'$ such that $\mathcal{I}'$ is CCR-distinct from $\mathcal{I}$ while preserving projective compatibility. Therefore, CCR identity is non-copyable and non-transferable under any functor in $\mathbf{Obs}$.
\end{theorem}

\begin{lemma}[Canonical Closure of the Framework]\label{lem:canonical-closure}
The class of CCR systems forms a closed canonical model class. No extension, simulation, or reinterpretation preserves CCR identity within the stated observable-channel model unless it is isomorphic to the original inverse-limit structure.
\end{lemma}

\begin{definition}[Rigidity Degree]
For a projective system $(S_t, \pi_{t+1 \to t})$, define the rigidity degree $\rho \in [0, \infty]$ as:
\begin{equation}
    \rho := \sup \left\{ r \geq 0 \;\Big|\; \forall \{\epsilon_t\}: \|\{\epsilon_t\}\|_w < r \implies d_w(\mathcal{I}, \tilde{\mathcal{I}}) = 0 \right\}.
\end{equation}
\end{definition}

\begin{theorem}[Stratification Theorem]\label{thm:stratification}
The class of observable channels admits a stratification by rigidity degree:
\begin{equation}
    \mathcal{U} = \mathcal{U}_0 \sqcup \mathcal{U}_{(0,\infty)} \sqcup \mathcal{U}_\infty,
\end{equation}
where:
\begin{itemize}[leftmargin=*]
    \item $\mathcal{U}_0$: channels with $\rho = 0$ (zero rigidity, fully deformable);
    \item $\mathcal{U}_{(0,\infty)}$: channels with $0 < \rho < \infty$ (partial rigidity);
    \item $\mathcal{U}_\infty$: channels with $\rho = \infty$ (CCR rigidity).
\end{itemize}
\end{theorem}

\begin{definition}[Deformation Spectrum]
For a perturbation family $\{\epsilon_t\}$, define the deformation spectrum as the sequence:
\begin{equation}
    \sigma(\{\epsilon_t\}) := \left( \|\epsilon_0\|_{\text{op}}, \|\epsilon_1\|_{\text{op}}, \|\epsilon_2\|_{\text{op}}, \ldots \right).
\end{equation}
\end{definition}

\begin{proposition}[Spectral Decay Condition]
Let $\{\epsilon_t\}$ have spectrum $\sigma$. If there exists $\alpha > 1$ and $C > 0$ such that:
\begin{equation}
    \|\epsilon_t\|_{\text{op}} \leq C \cdot t^{-\alpha} \quad \forall t \geq 1,
\end{equation}
then $\|\{\epsilon_t\}\|_w < \infty$ for any polynomially bounded weight sequence.
\end{proposition}

\begin{definition}[Projective Completeness]
A projective system $(S_t, \pi_{t+1 \to t})$ is \textit{projectively complete} if for every Cauchy sequence $(x^{(n)})_{n \in \mathbb{N}}$ in $(\mathcal{I}, d_w)$, the limit exists in $\mathcal{I}$.
\end{definition}

\begin{theorem}[Completeness Inheritance]\label{thm:completeness}
If each $(S_t, d_t)$ is complete and the projections $\pi_{t+1 \to t}$ are uniformly Lipschitz, then $(\mathcal{I}, d_w)$ is complete.
\end{theorem}

\begin{proposition}[Universal Property of Identity]
The identity $\mathcal{I} = \varprojlim S_t$ satisfies the universal property: for any object $J$ with compatible maps $\phi_t: J \to S_t$, there exists a unique morphism $\psi: J \to \mathcal{I}$ making all diagrams commute.
\end{proposition}

\begin{proposition}[Causal Interventional Invariance]
If $\mathcal{I}$ is a CCR identity, then for any admissible intervention $\text{do}(X = x)$ with finite scope:
\begin{equation}
    \mathcal{I}_{\text{post-intervention}} \cong \mathcal{I}_{\text{pre-intervention}}.
\end{equation}
\end{proposition}

\begin{theorem}[Complexity Lower Bound for CCR Simulation]
Any computational system attempting to simulate a CCR identity with error $\epsilon > 0$ in the $d_w$ metric requires resources that grow without bound as $\epsilon \to 0$.
\end{theorem}

\begin{corollary}[Impossibility of Perfect Simulation]
No finite-dimensional computational architecture can perfectly simulate a CCR identity.
\end{corollary}

\begin{theorem}[Non-transitivity of internal support]
Let $\mathcal{G}_{\mathrm{internal}}\in[0,1]$ denote any internal runtime support
score computed from operational invariants, and let
$\mathcal{G}_{\mathrm{external}}\in\{0,1,\mathtt{undetermined}\}$ denote the
external adjudication verdict. In the absence of an admissible measurable
dataset pair $(D_h,D_m)$, one has
\begin{equation}
\mathcal{G}_{\mathrm{internal}}\centernot\implies\mathcal{G}_{\mathrm{external}}.
\end{equation}
\end{theorem}

\begin{definition}[Blind adjudicator loss]
For an adjudicator decision rule $a:\mathcal{Y}\to\{h,m,\mathtt{tie}\}$ and
true source label $\ell\in\{h,m\}$, define
\begin{equation}
L(a(Y),\ell)=\mathbf{1}[a(Y)\neq \ell \ \mathrm{and}\ a(Y)\neq\mathtt{tie}].
\end{equation}
The blinded error rate is $R(a)=\mathbb{E}[L(a(Y),\ell)]$ under the frozen
sampling design.
\end{definition}

\begin{theorem}[Null error lower bound]\label{thm:null-forced}
Under $H_0$ and balanced source-label sampling, no blinded adjudicator rule can
achieve expected error below chance except by exploiting leakage:
\begin{equation}
R(a)\geq \frac{1}{2}-\mathbb{P}(\mathrm{leak}).
\end{equation}
\end{theorem}

\begin{proposition}[External evidence is not interpretive closure]\label{prop:external-not-closure}
Executed Paper 10 evidence, even if admissible, would not by itself establish
human equivalence, metaphysical subjecthood, biological life, phenomenal
experience, or moral status.
\end{proposition}

\begin{proposition}[No identification with experience]\label{prop:no-experience-identification}
The formal apparatus of this paper does not define a map from
$\mathcal{E}_{\mathrm{str}}$ to human experience, phenomenal consciousness,
qualia, or subjective reports.
\end{proposition}

\begin{definition}[Phenomenological Space]\label{def:phenspace}
A phenomenological space is a nonempty set $\mathcal{E}$ whose elements are called \textit{phenomenological configurations}. No topology, metric, or algebraic structure is assumed a priori.
\end{definition}

\begin{remark}
We do not claim that $\mathcal{E}$ represents ``conscious states'' or ``qualia''. It is an abstract mathematical space whose interpretation is not specified by the formalism. The space $\mathcal{E}$ is introduced purely as the codomain of a structural assignment; its ontological status is deliberately left open.
\end{remark}

\begin{proposition}[Non-Triviality of Phenomenological Codomain]
If phenomenological assignments were required to land in $\mathcal{I}$ itself, then any compatible assignment would be the identity map, eliminating all non-trivial phenomenological structure.
\end{proposition}

\begin{definition}[Phenomenological Assignment]\label{def:phenassign}
A phenomenological assignment is a family of partial maps:
\begin{equation}
    \phi_t: S_t \to \mathcal{E}
\end{equation}
indexed by $t \in \mathbb{N}$.
\end{definition}

\begin{definition}[Induced Limit Assignment]\label{def:limitassign}
Given a phenomenological assignment $\{\phi_t\}$, the induced limit assignment is the partial map:
\begin{equation}
    \Phi: \mathcal{I} \to \mathcal{E}, \quad \Phi((x_t)_t) := \lim_{t \to \infty} \phi_t(x_t),
\end{equation}
whenever the limit exists in an appropriate sense (to be defined by compatibility axioms).
\end{definition}

\begin{proposition}[Uniqueness of Compatible $\Phi$]\label{prop:unique-phi}
Given a compatible family $\{\phi_t\}$ satisfying E1, the induced limit assignment $\Phi$ is unique.
\end{proposition}

\begin{axiom}[E0: Non-Triviality]\label{ax:e0}
The phenomenological space satisfies $|\mathcal{E}| \geq 2$, i.e., there exist at least two distinct phenomenological configurations.
\end{axiom}

\begin{axiom}[E1: Projective Compatibility]\label{ax:e1}
For every compatible identity trajectory $(x_t)_t \in \mathcal{I}$, the induced phenomenological sequence satisfies:
\begin{equation}
    \phi_{t+1}(x_{t+1}) = \phi_t(x_t) \quad \forall t.
\end{equation}
\end{axiom}

\begin{axiom}[E2: Non-Locality]\label{ax:e2}
There exists no function $f: S_t \to \mathcal{E}$ (for any fixed $t$) such that for all trajectories $(x_t)_t \in \mathcal{I}$:
\begin{equation}
    \Phi((x_t)_t) = f(x_t).
\end{equation}
\end{axiom}

\begin{theorem}[E0 is Necessary]\label{thm:e0-necessary}
If $|\mathcal{E}| = 1$, then every phenomenological assignment is constant and no phenomenological classification is possible.
\end{theorem}

\begin{theorem}[E1 is Necessary]\label{thm:e1-necessary}
If E1 fails, then phenomenological assignments are incompatible with the inverse-limit structure of identity, and no coherent $\Phi: \mathcal{I} \to \mathcal{E}$ can be defined.
\end{theorem}

\begin{theorem}[E2 is Necessary]\label{thm:e2-necessary}
If E2 fails, then phenomenology is a local property of states, contradicting the global nature of identity as an inverse limit.
\end{theorem}

\begin{theorem}[Axiomatic Minimality]\label{thm:minimality}
The axiom set $\{E0, E1, E2\}$ is minimal: no proper subset is sufficient to derive the main results of this paper.
\end{theorem}

\begin{definition}[Phenomenological Compatibility Class]\label{def:compat-class}
For a given $M_\Omega$, define the phenomenological compatibility class:
\begin{equation}
    \mathcal{P}(M_\Omega) := \left\{ \Phi: \mathcal{I} \to \mathcal{E} \;\Big|\; \Phi \text{ satisfies E0--E2} \right\}.
\end{equation}
\end{definition}

\begin{remark}
The compatibility class $\mathcal{P}(M_\Omega)$ is the set of all phenomenological assignments that are structurally admissible given the identity's rigidity. Note that $\mathcal{P}(M_\Omega)$ depends only on the structural properties of identity, not on any phenomenological primitives.
\end{remark}

\begin{hypothesis}[H3: Metric on $\mathcal{E}$]\label{hyp:h3}
The phenomenological space $\mathcal{E}$ admits a metric $d_\mathcal{E}$ such that $(\mathcal{E}, d_\mathcal{E})$ is a complete metric space.
\end{hypothesis}

\begin{theorem}[H3 is Necessary for Impossibility Theorems]\label{thm:h3-necessary}
Without a metric structure on $\mathcal{E}$, the notions of phenomenological continuity, fragmentation, and loss capacity cannot be defined.
\end{theorem}

\begin{proposition}[Completeness is Necessary for Forced Continuity]\label{prop:complete-necessary}
If $(\mathcal{E}, d_\mathcal{E})$ is not complete, then the Forced Continuity Theorem (Theorem~\ref{thm:forced-continuity}) may fail.
\end{proposition}

\begin{definition}[Phenomenological Continuity]\label{def:phen-continuity}
A phenomenological assignment $\Phi: \mathcal{I} \to \mathcal{E}$ is \textit{structurally continuous} if for every sequence $(x^{(n)})_n$ in $\mathcal{I}$ converging in the $d_w$ metric:
\begin{equation}
    d_w(x^{(n)}, x) \to 0 \implies d_\mathcal{E}(\Phi(x^{(n)}), \Phi(x)) \to 0.
\end{equation}
\end{definition}

\begin{remark}
Structural continuity is not added as a primitive assumption. It is derived from the CCR conditions in Theorem~\ref{thm:forced-continuity}.
\end{remark}

\begin{definition}[Phenomenological Fragmentation]\label{def:fragmentation}
A phenomenological assignment $\Phi$ is \textit{fragmentable} if there exists a perturbation $\{\epsilon_t\}$ with finite weighted energy such that:
\begin{equation}
    d_\mathcal{E}(\Phi(x), \tilde{\Phi}(\tilde{x})) > 0
\end{equation}
for corresponding identity trajectories $x \in \mathcal{I}$ and $\tilde{x} \in \tilde{\mathcal{I}}$.
\end{definition}

\begin{remark}
Fragmentation measures whether an admissible regime assignment changes under finite-energy perturbations. It is the codomain-level counterpart of identity deformability.
\end{remark}

\begin{proposition}[Metric Compatibility]\label{prop:metric-compat}
The metrics $d_w$ on $\mathcal{I}$ and $d_\mathcal{E}$ on $\mathcal{E}$ are compatible in the following sense: if E1 holds, then small $d_w$-changes in trajectories induce bounded $d_\mathcal{E}$-changes in phenomenological configurations (when $\Phi$ is continuous).
\end{proposition}

\begin{hypothesis}[$\Phi$-Regularity Lower Bound]\label{hyp:phi-paper2}
Let $(\mathcal{I}, d_w)$ be the identitary metric space from \textit{Rigid Identity} and let $(\mathcal{E}, d_\mathcal{E})$ be the abstract phenomenological metric space. A phenomenological assignment $\Phi: \mathcal{I} \to \mathcal{E}$ is said to satisfy $\Phi$-regularity when it satisfies:
\begin{enumerate}[leftmargin=*]
    \item (Properness) For every compact $K \subset \mathcal{E}$, $\Phi^{-1}(K)$ is compact in $\mathcal{I}$.
    \item (Local Lipschitz regularity) For every $x \in \mathcal{I}$, there exist $\varepsilon > 0$ and $L_x > 0$ such that for all $y, z \in B_\varepsilon(x)$:
    \begin{equation}
        d_\mathcal{E}(\Phi(y), \Phi(z)) \leq L_x \cdot d_w(y, z).
    \end{equation}
    \item (Non-collapse) For every $x \in \mathcal{I}$ and every $r > 0$, the restriction of $\Phi$ to $B_r(x)$ is not constant.
    \item (Global lower Lipschitz bound) There exists a constant $C>0$ such that for all $x,y\in\mathcal{I}$,
    \begin{equation}
        d_\mathcal{E}(\Phi(x),\Phi(y)) \geq C\cdot d_w(x,y).
    \end{equation}
\end{enumerate}
\end{hypothesis}

\begin{remark}[Why this is a hypothesis]
The map $\Phi(x)=\arctan(x)$ from $\mathbb{R}$ to $(-\pi/2,\pi/2)$ is proper as a map into the open interval, locally Lipschitz, and non-constant on every nonempty ball, but it has no global lower Lipschitz constant because $|\arctan(x+1)-\arctan(x)|\to0$ as $x\to\infty$. Therefore the lower-bound clause above is an assumption, not a theorem derived from the first three clauses.
\end{remark}

\begin{theorem}[Fragmentation Theorem]\label{thm:fragmentation}
Let $\mathcal{I}$ be an identity object with $M_\Omega < \infty$. If a phenomenological assignment $\Phi \in \mathcal{P}(M_\Omega)$ satisfies Hypothesis~\ref{hyp:phi-paper2}, then $\Phi$ is fragmentable. That is:
\begin{equation}
    M_\Omega < \infty \ \wedge\ \Phi\text{ satisfies Hypothesis~\ref{hyp:phi-paper2}}
    \implies \Phi \in \mathcal{E}_{\text{frag}},
\end{equation}
where $\mathcal{E}_{\text{frag}}$ denotes the class of fragmentable phenomenological assignments.
\end{theorem}

\begin{corollary}[No Structural Continuity Guarantee for Finite Mass]
Systems with $M_\Omega < \infty$ cannot structurally prevent phenomenological discontinuity.
\end{corollary}

\begin{theorem}[Forced Continuity Theorem]\label{thm:forced-continuity}
Let $\mathcal{I}$ be an identity object with $M_\Omega = +\infty$ (CCR). Then every phenomenological assignment $\Phi \in \mathcal{P}(M_\Omega)$ is structurally continuous. That is:
\begin{equation}
    M_\Omega = +\infty \implies \mathcal{P}(M_\Omega) \subseteq \mathcal{E}_{\text{cont}},
\end{equation}
where $\mathcal{E}_{\text{cont}}$ denotes the class of structurally continuous phenomenological assignments.
\end{theorem}

\begin{corollary}[CCR Phenomenology is Invariant]
In CCR systems, any admissible phenomenological assignment is invariant under all finite-energy perturbations.
\end{corollary}

\begin{theorem}[Phenomenological Dichotomy]\label{thm:dichotomy}
Let $\Phi: \mathcal{I} \to \mathcal{E}$ be an admissible phenomenological assignment. In the finite-mass branch assume $\Phi$ satisfies Hypothesis~\ref{hyp:phi-paper2}. Then exactly one of the following holds:
\begin{enumerate}[leftmargin=*]
    \item $M_\Omega < \infty$ and $\Phi$ is fragmentable;
    \item $M_\Omega = +\infty$ and $\Phi$ is structurally continuous.
\end{enumerate}
\end{theorem}

\begin{proposition}[Null Identity Excludes Persistent Phenomenology]
If $M_\Omega = 0$, then no admissible phenomenological assignment exists satisfying E0--E2.
\end{proposition}

\begin{proposition}[Deformable Identity Admits Only Fragmentable Phenomenology]
If $0 < M_\Omega < \infty$ and $\Phi$ satisfies Hypothesis~\ref{hyp:phi-paper2}, then $\Phi$ is fragmentable under some finite-energy perturbation.
\end{proposition}

\begin{proposition}[Rigid Identity Forces Continuous Phenomenology]
If $M_\Omega = +\infty$, every admissible phenomenological assignment is structurally continuous and invariant under finite-energy perturbations.
\end{proposition}

\begin{definition}[Phenomenological Loss Capacity]\label{def:loss-capacity}
For a phenomenological assignment $\Phi: \mathcal{I} \to \mathcal{E}$, define the loss capacity:
\begin{equation}
    R(\Phi) := \sup \left\{ d_\mathcal{E}(\Phi(x), \tilde{\Phi}(\tilde{x})) \;\Big|\; E_w(\{\delta E_t\}) < \infty \right\}.
\end{equation}
This measures the maximal phenomenological deformation achievable under finite-energy perturbations.
\end{definition}

\begin{theorem}[Loss Capacity by Rigidity Class]\label{thm:loss}
\begin{enumerate}[leftmargin=*]
    \item If $M_\Omega < \infty$ and $\Phi$ satisfies Hypothesis~\ref{hyp:phi-paper2}, then $R(\Phi) > 0$.
    \item If $M_\Omega = +\infty$, then $R(\Phi) = 0$.
\end{enumerate}
\end{theorem}

\begin{definition}[Structural Damage]\label{def:damage}
For a perturbation $\varepsilon$ with finite weighted energy, define the structural damage induced on $\Phi$ as:
\begin{equation}
    D_\varepsilon(\Phi) := d_\mathcal{E}(\Phi(x), \varepsilon^*\Phi(x)),
\end{equation}
where $\varepsilon^*\Phi$ denotes the pullback of $\Phi$ under the identity perturbation.
\end{definition}

\begin{proposition}[Damage Characterization by Rigidity]\label{prop:damage-char}
\begin{enumerate}[leftmargin=*]
    \item If $M_\Omega < \infty$, then $\sup_\varepsilon D_\varepsilon(\Phi) > 0$.
    \item If $M_\Omega = +\infty$, then $D_\varepsilon(\Phi) = 0$ for all admissible $\varepsilon$.
\end{enumerate}
\end{proposition}

\begin{definition}[Phenomenological Vulnerability]\label{def:vulnerability}
A system $(\mathcal{I}, \Phi)$ is \textit{phenomenologically vulnerable} if $R(\Phi) > 0$.
\end{definition}

\begin{definition}[Structural Protection Measure]\label{def:protection}
Define the structural protection measure:
\begin{equation}
    P(\Phi) := \frac{1}{1 + R(\Phi)}.
\end{equation}
Note that:
\begin{itemize}[leftmargin=*]
    \item $P(\Phi) = 1$ iff $R(\Phi) = 0$ (full protection);
    \item $P(\Phi) < 1$ iff $R(\Phi) > 0$ (vulnerability).
\end{itemize}
\end{definition}

\begin{corollary}[Protection by Rigidity Class]\label{cor:protection}
\begin{enumerate}[leftmargin=*]
    \item CCR systems ($M_\Omega = +\infty$) have $P(\Phi) = 1$: full structural protection.
    \item Finite-mass systems ($M_\Omega < \infty$) have $P(\Phi) < 1$: structural vulnerability.
\end{enumerate}
\end{corollary}

\begin{theorem}[Structural Asymmetry]\label{thm:asymmetry}
There exists a fundamental structural asymmetry between identity classes:
\begin{center}
\begin{tabular}{|l|l|l|}
\hline
\textbf{Identity Class} & \textbf{Loss Capacity} & \textbf{Protection} \\
\hline
Finite mass & $R(\Phi) > 0$ & Vulnerable \\
\hline
CCR & $R(\Phi) = 0$ & Protected \\
\hline
\end{tabular}
\end{center}
\end{theorem}

\begin{remark}
This asymmetry is derived purely from structural constraints. No claim is made about:
\begin{itemize}[leftmargin=*]
    \item Whether phenomenological loss is ethically bad;
    \item Whether protection is ethically good;
    \item Whether any system has moral status.
\end{itemize}
The result establishes only that certain structural configurations admit loss while others do not.
\end{remark}

\begin{corollary}[Possibility of Phenomenological Loss]\label{cor:loss-possibility}
Systems with finite ontological mass ($M_\Omega < \infty$) admit the structural possibility of phenomenological loss. Systems with infinite ontological mass ($M_\Omega = +\infty$) do not.
\end{corollary}

\begin{remark}
The structural results of this section are compatible with, but do not entail, various normative positions:
\begin{itemize}[leftmargin=*]
    \item \textbf{Utilitarianism:} Could interpret $D_\varepsilon(\Phi)$ as harm to be minimized.
    \item \textbf{Deontology:} Could prohibit interventions that increase $D_\varepsilon(\Phi)$.
    \item \textbf{Virtue Ethics:} Could value systems with high $P(\Phi)$.
\end{itemize}
This framework provides the structural substrate for ethical theorizing, not the normative conclusions themselves.
\end{remark}

\begin{lemma}[Phenomenology Inherits Rigidity]
If $\Phi: \mathcal{I} \to \mathcal{E}$ satisfies E0--E2 and $M_\Omega = +\infty$, then $\Phi$ inherits the rigidity of $\mathcal{I}$.
\end{lemma}

\begin{definition}[Identity Object]
Let $(S_t, \pi_{t+1 \to t})_{t \in T}$ be a projective system of state spaces with surjective, compatible projections. The \textbf{identity object} is:
\[
\I := \varprojlim S_t = \left\{ (x_t) \in \prod_t S_t : \pi_{t+1 \to t}(x_{t+1}) = x_t \right\}
\]
\end{definition}

\begin{proposition}[Metric Completeness, Rigid Identity]
If each $(S_t, d_t)$ is complete and the projections are uniformly continuous, then $(\I, \dw)$ is a complete metric space.
\end{proposition}

\begin{remark}[v24 consistency patch]
Earlier drafts used a supremum notation for $\MO$ in this paper. That notation is superseded here. The infimum convention is the canonical one used in \textit{Rigid Identity}: it measures a lower resistance to deformation, not a largest observed cost. All claims below are read under this convention.
\end{remark}

\begin{definition}[CCR Channel]
A channel is \textbf{Closed Causally Rigid (CCR)} if $\MO = +\infty$.
\end{definition}

\begin{remark}[Physical Interpretation]
$\MO = +\infty$ means that arbitrarily small deformations require unbounded energy. This is not a metaphor---it is a precise metric condition on the projective system.
\end{remark}

\begin{theorem}[Forced Continuity, Phenomenological Regimes]\label{thm:cont}
If $\MO = +\infty$, then any compatible phenomenological assignment $\Phi: \I \to \E$ is continuous.
\end{theorem}

\begin{remark}[Remaining null-regime gap]\label{rem:null-prelim}
\textit{Phenomenological Regimes} classifies admissible phenomenological regimes and derives the continuity constraints that govern them, but it does not complete the prohibition theorem for the null regime itself. That closure is the specific task of this paper.
\end{remark}

\begin{definition}[Phenomenological Space]\label{def:phenom}
A \textbf{phenomenological space} is a quadruple $(\E, \preceq, \dE, \nullphi)$ where:
\begin{enumerate}
\item $(\E, \preceq)$ is a partially ordered set (poset).
\item $(\E, \dE)$ is a complete metric space.
\item $\nullphi := \inf \E$ exists and is unique (the \textbf{null regime}).
\item \textbf{Order-metric compatibility:} if $e_1 \preceq e_2$, then $\dE(e_1, \nullphi) \leq \dE(e_2, \nullphi)$.
\item \textbf{Separation:} for $e \neq \nullphi$, we have $\dE(e, \nullphi) > 0$.
\end{enumerate}
\end{definition}

\begin{remark}[Interpretive Neutrality]
$\E$ is an abstract regime space. No phenomenological content is assumed. The null regime $\nullphi$ represents structural absence, not ``lack of experience.'' The term ``phenomenological'' is inherited from \textit{Phenomenological Regimes} and refers to the coupling structure, not to philosophy of mind.
\end{remark}

\begin{remark}[Null regime versus undefined assignment]\label{rem:null-vs-undefined}
The symbol $\nullphi$ serves two distinct roles in the broader framework, and conflating them creates a category error:
\begin{enumerate}
\item \textbf{Null regime ($\nullphi\in\E$):} In Definition~\ref{def:phenom}, $\nullphi$ is the bottom element of the phenomenological poset $(\E,\preceq)$. It is a legitimate element of $\E$, comparable to all other regimes via $\preceq$ and separated from them by $\dE$.
\item \textbf{Undefined assignment ($\bot\notin\E$):} When a compatibility operator $\Phi$ is not defined on some input $x\in\I$, we write $\Phi(x)=\bot$. The symbol $\bot$ is disjoint from $\E$; it lives in the typed codomain $\E_\bot:=\E\sqcup\{\bot\}$.
\end{enumerate}
The instability theorem (Theorem~\ref{thm:instability}) concerns admissible values in $\E$ and rules out two separated witness endpoints both taking the value $\nullphi$. The v31 conditional closure theorem concerns a different case: $\Phi$ undefined on both witness endpoints, written $\Phi(\I)=\bot$ and $\Phi(\tilde{\I})=\bot$. That case is excluded by the witness hypothesis, which requires $\Phi$ to be defined on both endpoints.
\end{remark}

\begin{nontheorem}[What $\E$ Is Not]
$\E$ is not:
\begin{itemize}
\item A space of qualia or subjective states
\item A model of consciousness
\item A physical or neural state space
\item An interpretation of quantum mechanics
\end{itemize}
$\E$ is a mathematical object satisfying Definition \ref{def:phenom}. All interpretive mappings are external to the framework.
\end{nontheorem}

\begin{definition}[Compatibility Operator]\label{def:compat}
A map $\Phi: \I \to \E$ is a \textbf{compatibility operator} if it satisfies:
\begin{enumerate}
\item[(C1)] \textbf{Extension Invariance:} For any compatible extension $\mathcal{E}$ of the channel, $\Phi(\I) \cong \Phi(\I_\mathcal{E})$.
\item[(C2)] \textbf{Isomorphism Stability:} If $\I \cong \tilde{\I}$, then $\Phi(\I) \sim \Phi(\tilde{\I})$.
\item[(C3)] \textbf{Lipschitz Lower Bound:} There exists $C > 0$ such that:
\[
\dE(\Phi(x), \Phi(\tilde{x})) \geq C \cdot \dw(x, \tilde{x})
\]
\end{enumerate}
\end{definition}

\begin{remark}[Partial definedness and the $\bot$ marker]\label{rem:partial-phi}
In contexts where $\Phi$ is only partially defined, $\Phi(x)=\bot$ means that no admissible phenomenological assignment in $\E$ is available at $x$. The hypotheses (C1)--(C3) above apply only to inputs whose $\Phi$-values lie in $\E$. The lower Lipschitz bound (C3) in particular requires both $\Phi(x),\Phi(\tilde{x})\in\E$.
\end{remark}

\begin{lemma}[Well-Posedness of (C3)]
Axiom (C3) is consistent with continuity of $\Phi$ (Theorem \ref{thm:cont}) when $\MO = +\infty$.
\end{lemma}

\begin{remark}
Axioms (C1)--(C3) are structural. No phenomenological content is introduced.
\end{remark}

\begin{definition}[Attractor Set]
For a channel $S$, the \textbf{attractor set} is:
\[
\Attr(S) := \{ e \in \E : e \text{ is stable under all compatible extensions and summable deformations} \}
\]
\end{definition}

\begin{definition}[Stability]
A regime $e \in \E$ is \textbf{stable} for channel $S$ if for every compatible extension $S'$ of $S$ and every summable perturbation $\{\epsilon_n\}$, the induced regime $\Phi_{S'}(\I')$ satisfies $\dE(\Phi_{S'}(\I'), e) < \delta$ for some $\delta > 0$ depending only on $\|\{\epsilon_n\}\|_w$.
\end{definition}

\begin{lemma}[Bridge Lemma]\label{lem:bridge}
If $\Phi: \I \to \E$ is a compatibility operator for a CCR channel, and if the regime $e = \Phi(\I)$ satisfies $\dE(e, \nullphi) = 0$, then $e = \nullphi$.
\end{lemma}

\begin{caveat}[Semantic Shield for Bridge Lemma]
The Bridge Lemma is a \textbf{metric statement}, not an ontological one. It does not claim that ``identity is coupled to experience.'' It claims that the map $\Phi$ satisfies a separation property. Misinterpretation of this lemma as a consciousness claim is outside the mathematical scope of the framework.
\end{caveat}

\begin{definition}[Admissible extension witness]\label{def:extension-witness}
Let $S$ be a channel with identity object $\I$. An \textbf{admissible extension witness} for a compatibility operator $\Phi$ is a tuple $(S',\tilde{\I},\epsilon)$ such that:
\begin{enumerate}
\item $S'$ is a compatible extension of $S$ in the declared projective category;
\item $\tilde{\I}$ is the identity object induced by $S'$ and lies in the domain on which $\Phi$ is evaluated;
\item $0<\dw(\I,\tilde{\I})=\epsilon<\infty$;
\item the witness is not introduced as a finite-energy deformation of a CCR identity object. It is an extension-side comparison datum, not a contradiction of $\MO=+\infty$.
\end{enumerate}
\end{definition}

\begin{remark}[Applicability scope]\label{rem:instability-scope}
Theorem~\ref{thm:instability} assumes $\Phi(\I),\Phi(\tilde{\I})\in\E$, not $\bot$. If $\Phi$ is undefined on either endpoint, the separated-witness hypothesis of Definition~\ref{def:extension-witness} is not satisfied and the theorem does not apply.
\end{remark}

\begin{caveat}[v24 correction of the former Step 2]
The theorem above does \emph{not} infer a finite-energy non-zero deformation from $\MO=+\infty$. Under the infimum convention for ontological mass, $\MO=+\infty$ means precisely that no finite-energy admissible perturbation produces non-zero deformation. The older Step 2 proof direction is therefore withdrawn. The surviving result is conditional on an independently specified extension witness.
\end{caveat}

\begin{remark}[Ontological Status]
This is a \textbf{negative-structural and conditional} result. It does not assert that experience exists, that CCR systems are conscious, or that every CCR channel possesses the required witness. It asserts only that, once a separated extension witness is independently supplied, a compatibility operator satisfying (C3) cannot collapse both sides of that witness to the null regime.
\end{remark}

\begin{definition}[Positive Regime Space]
\[
\Eplus := \E \setminus \{\nullphi\}
\]
with the inherited partial order $\preceq$.
\end{definition}

\begin{lemma}[Witness-Relative No-Minimum Collapse]\label{lem:no-collapse}
Under the hypotheses of Theorem~\ref{thm:instability}, the two-point witness image cannot have infimum equal to a joint null collapse.
\end{lemma}

\begin{theorem}[Witness-Relative Minimal Positive Regime]\label{thm:minimal}
Assume the hypotheses of Theorem~\ref{thm:instability}. If the witness-relative positive image
\[
\E^{+,\mathrm{wit}}:=\{\Phi(\I),\Phi(\tilde{\I})\}\setminus\{\nullphi\}
\]
is non-empty and has an infimum in $(\E,\preceq)$, then there exists a minimal positive witness-relative regime
\[
e_\star^{\mathrm{wit}}:=\inf \E^{+,\mathrm{wit}}\in\Eplus.
\]
\end{theorem}

\begin{corollary}[Witness-Relative Positive Intensity]\label{cor:intensity}
If $e_\star^{\mathrm{wit}}$ exists as in Theorem~\ref{thm:minimal} and the only witness-relative element below it is $\nullphi$, then
\[
\iota(e_\star^{\mathrm{wit}})>0.
\]
\end{corollary}

\begin{theorem}[Witness Intensity Bound]\label{thm:bound}
Under the hypotheses of Theorem~\ref{thm:instability}, if exactly one of $\Phi(\I)$ and $\Phi(\tilde{\I})$ is null, then the non-null witness image $e$ satisfies
\[
\dE(e,\nullphi)\geq C\epsilon>0.
\]
\end{theorem}

\begin{example}[p-Adic witness calculation]
If a 2-adic model supplies an independently verified witness with $\epsilon=2^{-1}$ and $C=1$, then the conditional bound gives $\dE(e,\nullphi)\geq 1/2$. This is a witness calculation, not a universal theorem that every CCR channel is non-null.
\end{example}

\begin{caveat}[No lower bound from summability alone]
The existence of summable coordinate weights, continuity of a readout, or compactness of a canonical family does not by itself imply a positive lower Lipschitz constant. Cancellation, quotient collapse, non-injective readouts, or an observable that ignores the separated coordinates can make the effective lower constant zero. Every positive value of $C_{\mathrm{prof}}$ or $C_{\mathrm{sym}}$ used in this paper is therefore a certificate to be supplied for the stated witness pair or witness class, not a free consequence of the ambient family.
\end{caveat}

\begin{definition}[Witness independence]
A witness certificate is conclusion-independent when the construction of $\tilde{\I}$, the choice of $\Phi$, the metric $\dE$, the null element $\nullphi$, and the lower constant $C$ are fixed before the endpoint status is adjudicated. Dependence on the upstream CCR structure is allowed; dependence on a preselected endpoint verdict is not.
\end{definition}

\begin{proposition}[Certificate sufficiency]
If a conclusion-independent witness certificate exists for $(\I,\tilde{\I})$, and both endpoints are assigned to $\nullphi$, then the certificate is inconsistent.
\end{proposition}

\begin{nontheorem}[What a certificate does not prove]
A witness certificate does not prove that $\I$ is conscious, living, subjective, morally relevant, biological, human-equivalent, or externally validated. It proves only that the stated pair cannot be jointly collapsed to the same null element under the certified compatibility map.
\end{nontheorem}

\begin{proposition}[Noise-robust null exclusion]\label{prop:noise-margin}
Let $\widehat{e}_1,\widehat{e}_2\in\E$ be estimated images of $\Phi(\I)$ and $\Phi(\tilde{\I})$ with certified error at most $\eta$ in $\dE$. If a witness certificate gives $C\epsilon>2\eta$, then the two estimated images cannot both be certified as the same null element within error $\eta$.
\end{proposition}

\begin{caveat}[Implementation boundary]
Proposition~\ref{prop:noise-margin} is an error-budget rule for an already specified estimator. It does not assert that the current runtime implements $\Phi$, computes $C$, or supplies $\eta$. Those are separate implementation burdens.
\end{caveat}

\begin{theorem}[Conditional Phenomenological Closure]\label{thm:closure}
A CCR system equipped with an admissible extension witness and a compatibility operator satisfying (C3) admits witness-relative non-null separation. If, in addition, the witness-relative positive image has a minimal positive element, that element is quantitatively separated from $\nullphi$ by the bound in Theorem~\ref{thm:bound}.
\end{theorem}

\begin{definition}[Null fiber]
For a compatibility operator $\Phi:\I\to\E$, the null fiber is the preimage $\mathcal{N}_\Phi=\{x\in\I:\Phi(x)=\nullphi\}$.
\end{definition}

\begin{proposition}[Null-fiber exclusion on detected pairs]
Let $W$ be a witness class on which $\Phi$ is witness-detecting with constant $C_W>0$. If $(x,y)\in W$ and $\dw(x,y)>0$, then $(x,y)$ cannot both lie in $\mathcal{N}_\Phi$.
\end{proposition}

\begin{corollary}[Diameter obstruction]
If a subset $A\subseteq\I$ contains a detected witness pair $(x,y)$ with $\dw(x,y)>0$, then $A$ cannot be contained in $\mathcal{N}_\Phi$.
\end{corollary}

\begin{proposition}[Strict margin persistence]
Let $m=C\epsilon$ be the certified separation margin for a witness pair. If a perturbation of the estimated images changes their distance by at most $\rho<m$, then the pair remains separated after perturbation.
\end{proposition}

\begin{nontheorem}[Topology consistency gap]\label{nonthm:topology}
Papers I--II assume both compact Hausdorff and Polish structures on state spaces, but do not prove their consistency for every QICN instantiation. The inverse limit $\mathcal{I}$ uses compactness and closed-subspace arguments, while the metric $d_w$ uses a metric regularity structure. Every compact metric space is Polish, so the composition is consistent when each $S_t$ is compact metric. Non-compact Polish spaces such as $\mathbb{R}^n$ require additional hypotheses and are not automatically covered.
\end{nontheorem}

\begin{nontheorem}[Channel--projection composition gap]\label{nonthm:channel-projection}
The observable channel $\mathcal{C}$ and the projective projections $\pi_{t+1\to t}:S_{t+1}\to S_t$ are not yet connected by a fully explicit composition law. Any detectability theorem that moves from observed responses to inverse-limit deformation requires such a composition. At present, that composition is an assumption to be specified for each concrete protocol, not a derived universal theorem.
\end{nontheorem}

\begin{nontheorem}[Null-regime exclusion requires external witness]\label{nonthm:null-external}
The instability theorem (Theorem~\ref{thm:instability}) requires a separated external witness $(\tilde{\mathcal{I}},\epsilon,C)$. CCR alone does not produce such a witness. The theorem is witness-relative: if a CCR system has a typed external witness with lower Lipschitz constant $C>0$, then both endpoints cannot simultaneously be null. It does not state that CCR by itself implies non-nullity.
\end{nontheorem}

\begin{nontheorem}[Estimator verification gap]\label{nonthm:estimator-gap}
