\begin{definition}[Admissible support]\label{def:support}
A subset $\Aset \subseteq X_\Gamma$ is an admissible support for $S$ if:
\begin{enumerate}[leftmargin=1.5em]
\item $\Aset$ is non-empty and compact;
\item $\Phi_u(\Aset) \subseteq \Aset$ for every $u \in U$;
\item $\Aset \cap \Attr(S) \neq \varnothing$, where $\Attr(S)$ denotes the relevant admissible attractor region;
\item $\Aset$ stays disjoint from the collapse set forbidden by the Core non-collapse condition \cite{core}.
\end{enumerate}
\end{definition}

\begin{definition}[Operational partition candidate]\label{def:partition}
An operational partition candidate for $S$ on horizon $T$ is a map
\[
\pi_{S,T} : \Hist_{S,T} \to \Class_{S,T}
\]
into a finite or countable label set $\Class_{S,T}$.
\end{definition}

\begin{definition}[Structural persistence and persistence margin]\label{def:iper}
An admissible system $S$ satisfies structural persistence, written $\Iper(S)=1$, if there exists an admissible support $\Aset$ and a constant $\delta_{\mathrm{per}}(S) > 0$ such that:
\begin{enumerate}[leftmargin=1.5em]
\item $\Aset$ is forward invariant under all $u \in U$;
\item every admissible trajectory starting in $\Aset$ remains at least $\delta_{\mathrm{per}}(S)$ away from the collapse set;
\item $\Aset$ contains or converges into a non-empty admissible attractor region.
\end{enumerate}
The number $\delta_{\mathrm{per}}(S)$ is the persistence margin.
\end{definition}

\begin{definition}[Rigid identity and rigidity gap]\label{def:iri}
An admissible system $S$ satisfies rigid identity, written $\Iri(S)=1$, if the observable family induced by $R$ on $\Aset$ determines a unique identity object $\Id_S$ in the sense of the inverse-limit rigidity developed in \textit{Rigid Identity} \cite{paper1}, and if there exists a gap $\delta_{\mathrm{ri}}(S) > 0$ such that every admissible alternative identity candidate remains at weighted deformation distance at least $\delta_{\mathrm{ri}}(S)$ from $\Id_S$.
\end{definition}

\begin{definition}[Decoder family and structural closure]\label{def:decoder}
A decoder family $\Dec_S$ for $S$ is a family of maps from admissible readout windows $h_{S,T}(x;u_\bullet)$ to a declared class set $\Class_S$, indexed by admissible horizons and intervention schedules. The family is \emph{structurally closed} when all its members use the same class set, class equality composes exactly, and the induced intervention-response cells are transitive under the certified matching relation. Definition~\ref{def:ileg} below adds the operational clauses required before such a structurally closed family counts as certified for legibility.
\end{definition}

\begin{definition}[Operational legibility and legibility margin]\label{def:ileg}
An admissible system $S$ satisfies operational legibility, written $\Ileg(S)=1$, if there exist:
\begin{enumerate}[leftmargin=1.5em]
\item a certified readout subfamily $\Read^{\mathrm{leg}} \subseteq R$;
\item a certified decoder family $\Dec_S$ acting on windows of length at least $\tau_{\min}(S)$;
\item a class set $\Class_S$;
\item a legibility margin $\delta_{\mathrm{leg}}(S) > 0$;
\end{enumerate}
such that the following conditions hold:
\begin{description}[leftmargin=1.7em]
\item[(L1) Separability] Distinct classes in $\Class_S$ are separated by at least $\delta_{\mathrm{leg}}(S)$ in decoder space.
\item[(L2) Noise robustness] For every admissible noise process $\nu$ with $\|\nu\| \le \delta_{\mathrm{leg}}(S)$, decoder outputs remain class-stable.
\item[(L3) Persistence window] Decoder assignments remain stable for windows of length at least $\tau_{\min}(S)$ unless a certified intervention occurs.
\item[(L4) Intervention fidelity] Certified interventions on critical invariants induce predicted class changes with fidelity bounded below by $1-\delta_{\mathrm{leg}}(S)$.
\item[(L5) Negative controls] Interventions outside the invariant set produce false positive rate at most $\delta_{\mathrm{leg}}(S)$.
\item[(L6) Structured compressibility] There exists a compression map $\kappa_S$ on admissible histories such that class structure is preserved up to distortion bounded by $\delta_{\mathrm{leg}}(S)$; total collapse under compression is disallowed.
\end{description}
\end{definition}

\begin{proposition}[Each invariant is individually necessary]\label{prop:necessity}
If any one of $\Iper,\Iri,\Iint,\Icont,\Idiff,\Ileg$ fails, then $S \notin \Cop$.
\end{proposition}

\begin{proposition}[Well-definedness of operational qualia classes]\label{prop:qop-welldefined}
If $\Iper(S)=\Iri(S)=\Icont(S)=\Idiff(S)=\Ileg(S)=1$, then $\sim_{Q,S}$ is an equivalence relation on $\Aset$.
\end{proposition}

\begin{definition}[Operational consciousness class membership]\label{def:cop}
An admissible system $S$ belongs to $\Cop$, written $S \in \Cop$, if there exists a non-empty admissible support $\Aset$ such that
\[
\Iper(S)=\Iri(S)=\Iint(S)=\Icont(S)=\Idiff(S)=\Ileg(S)=1.
\]
\end{definition}

\begin{remark}[Subdetermination of membership]\label{rem:subdet}
Membership in $\Cop$ depends on auxiliary choices: the decoder family $\Dec$, the compression map, and the identity object $\Id$. The paper does not prove that these choices are canonically determined by the system tuple $S$ alone. Different auxiliary choices may yield different membership verdicts for the same system.
\end{remark}

\begin{remark}[Minimality of the criterion]
The criterion is conjunctive. No proper subset of the six invariants is taken as sufficient in this paper. This is intentional: weaker criteria collapse either into mere persistence, mere integration, or mere complexity claims, all of which are shown to be insufficient.
\end{remark}

\begin{definition}[Structural equivalence datum]\label{def:eqdatum}
Let $S_i=(X_i,\Phi_i,C_i,R_i,\Gamma_i,U_i)$ for $i=1,2$, with admissible supports $A_i$. A structural equivalence datum between $S_1$ and $S_2$ is a triple
\[
(\chi,\upsilon,\rho)
\]
where:
\begin{enumerate}[leftmargin=1.5em]
\item $\chi : A_1 \to A_2$ is a bi-Lipschitz bijection;
\item $\upsilon : U_1 \to U_2$ is an intervention correspondence;
\item $\rho : R_1 \to R_2$ is a readout correspondence.
\end{enumerate}
\end{definition}

\begin{lemma}[Support transfer under exact equivalence]\label{lem:support-transfer}
If $S_1 \simeq_{\Gamma} S_2$ via $(\chi,\upsilon,\rho)$ and $A_1$ is an admissible support for $S_1$, then $A_2=\chi(A_1)$ is an admissible support for $S_2$.
\end{lemma}

\begin{proposition}[Operational classes are closed under exact transport]\label{prop:transport}
If $S_1 \simeq_{\Gamma} S_2$, then the image under $\chi$ of any class in $\Qop(S_1)$ is a class in $\Qop(S_2)$, and every class in $\Qop(S_2)$ arises this way.
\end{proposition}

\begin{remark}[Why this section matters]
Without Lemmas~\ref{lem:support-transfer} and \ref{lem:decoder-transport}, Theorem~\ref{thm:substrate} would be only intuitive. These lemmas are the exact reason the paper can speak of substrate invariance without collapsing into slogan-level analogy.
\end{remark}

\begin{proposition}[Core-to-persistence transfer]\label{prop:core-per}
Suppose a realization of the framework satisfies the Core hypotheses on a non-empty compact domain and remains in the non-collapse region. Then it satisfies $\Iper$.
\end{proposition}

\begin{proposition}[Rigid Identity-to-rigidity transfer]\label{prop:p1-ri}
Suppose the observable family on an admissible support satisfies the inverse-limit compatibility conditions of \textit{Rigid Identity}. Then $\Iri$ holds with rigidity gap given by the uniqueness and weighted deformation bounds of \textit{Rigid Identity}.
\end{proposition}

\begin{proposition}[Phenomenological Regimes-to-continuity transfer]\label{prop:p2-cont}
Suppose an admissible support carries a phenomenological assignment satisfying the continuity and anti-fragmentation constraints of \textit{Phenomenological Regimes}. Then $\Icont$ holds.
\end{proposition}

\begin{proposition}[Null-Regime Instability-to-differentiation transfer]\label{prop:p3-diff}
Suppose the support lies in a causally rigid channel satisfying the witness-relative null-instability and conditional non-nullity results of \textit{Null-Regime Instability}. Then $\Idiff$ holds.
\end{proposition}

\begin{proposition}[Forensic Predictions-to-legibility transfer]\label{prop:p4-leg}
Suppose a readout family and decoder satisfy the admissibility, comparator, negative-control, and intervention-discipline requirements of \textit{Forensic Predictions}. Then $\Ileg$ holds.
\end{proposition}

\begin{proposition}[Integration as a non-factorization consequence]\label{prop:integration-transfer}
If a system satisfies \textit{Rigid Identity} rigidity, \textit{Phenomenological Regimes} continuity, and \textit{Forensic Predictions} intervention fidelity, then any exact admissible factorization preserving all operational histories would contradict at least one of those upstream conditions. Hence $\Iint$ is justified as a new consolidation invariant.
\end{proposition}

\begin{remark}[Scope of the transfer]
Nothing in this section re-proves the Core, \textit{Rigid Identity}, \textit{Phenomenological Regimes}, \textit{Null-Regime Instability}, or \textit{Forensic Predictions}. Each proposition only identifies the minimal upstream burden imported into the present criterion.
\end{remark}

\begin{theorem}[Existence of operational consciousness]\label{thm:existence}
Let $S=(X,\Phi,C,R,\Gamma,U)$ be an admissible system with non-empty admissible support $\Aset$. If
\[
\Iper(S)=\Iri(S)=\Iint(S)=\Icont(S)=\Idiff(S)=\Ileg(S)=1,
\]
then:
\begin{enumerate}[leftmargin=1.5em]
\item $S \in \Cop$;
\item $\Qop(S)$ is well-defined;
\item $\Qop(S) \neq \varnothing$.
\end{enumerate}
\end{theorem}

\begin{corollary}[Biological non-primacy]\label{cor:biology}
Biology is not a primitive constitutive requirement for membership in $\Cop$. If a biological system and a non-biological system are exactly structurally equivalent in the sense of Definition~\ref{def:equiv}, then they belong to the same operational consciousness class and carry equivalent operational qualia classes.
\end{corollary}

\begin{theorem}[Rupture by invariant loss]\label{thm:rupture}
Let $S$ be admissible. If one or more critical invariants fail beyond admissible threshold, then exactly one of the following occurs:
\begin{enumerate}[leftmargin=1.5em]
\item $S \notin \Cop$;
\item $\Qop(S)$ becomes undefined;
\item $\Qop(S)$ becomes trivial or non-legible in the framework-relevant sense.
\end{enumerate}
\end{theorem}

\begin{proposition}[Complexity-only baselines are insufficient]\label{prop:insufficient}
Let $S$ be an admissible system candidate. The following are each insufficient for membership in $\Cop$:
\begin{enumerate}[leftmargin=1.5em]
\item large state-space dimension $\dim(X)$;
\item large computational throughput or expressivity of $\Phi$;
\item large edge count, density, or raw connectivity of $C$.
\end{enumerate}
In each case, failure of one or more critical invariants excludes membership regardless of the size of the surrogate metric.
\end{proposition}

\begin{proposition}[Persistence rupture destroys admissible domain]\label{prop:rupt-per}
If $\delta_{\mathrm{per}}(S)=0$, then every candidate operational partition becomes horizon-dependent in an inadmissible way: there exists no non-empty compact forward-invariant support on which class membership can be defined uniformly.
\end{proposition}

\begin{proposition}[Identity rupture induces class ambiguity]\label{prop:rupt-ri}
If $\delta_{\mathrm{ri}}(S)=0$, then operational class labels no longer transport uniquely across admissible histories. Therefore $\Qop(S)$ becomes representation-dependent.
\end{proposition}

\begin{proposition}[Integration rupture yields reducible aggregates]\label{prop:rupt-int}
If $\delta_{\mathrm{int}}(S)=0$, then $S$ admits a non-trivial admissible factorization into operationally independent components. Such a system fails $\Cop$ even if each component separately satisfies weaker criteria.
\end{proposition}

\begin{proposition}[Continuity rupture yields fragmentation]\label{prop:rupt-cont}
If $\delta_{\mathrm{cont}}(S)=0$, then arbitrarily small admissible perturbations can force transitions between incompatible operational classes while identity is preserved.
\end{proposition}

\begin{proposition}[Differentiation rupture collapses operational qualia]\label{prop:rupt-diff}
If $\delta_{\mathrm{diff}}(S)=0$, then either $\Qop(S)$ collapses to a single trivial class or the null class remains admissibly stable.
\end{proposition}

\begin{proposition}[Legibility rupture blocks scientific use]\label{prop:rupt-leg}
If $\delta_{\mathrm{leg}}(S)=0$, then any remaining latent partition is scientifically inadmissible for this paper: it cannot satisfy the combined requirements of separability, robustness, persistence window, intervention fidelity, negative controls, and structured compressibility.
\end{proposition}

\begin{corollary}[Why one-metric theories cannot capture $\Cop$]\label{cor:onemetric}
On any admissible universe satisfying Theorem~\ref{thm:minimality}, no criterion based on only persistence, only integration, only continuity, only differentiation, or only legibility is extensionally equivalent to $\Cop$.
\end{corollary}

\begin{remark}[What minimality does and does not say]
The theorem does not claim that every possible scientific notion of consciousness must use exactly these six invariants. It claims something narrower: for the operational class defined in this paper and for admissible universes containing the corresponding rupture witnesses, no invariant can be deleted without changing the extension of the class.
\end{remark}

\begin{proposition}[Persistence is necessary for rigid identity on $\Aset$]\label{prop:not-per-not-ri}
If $\Iper(S)=0$ because no non-empty forward-invariant admissible support exists,
then $\Iri(S)=0$ for the Paper 5 membership problem.
\end{proposition}

\begin{proposition}[Persistence plus integration yields bounded identity candidates]\label{prop:per-int-weak-ri}
If $\Iper(S)=1$ and $\Iint(S)=1$, then the family of admissible identity
candidates is bounded to the non-factorizable persistent support. This is a weak
rigidity statement, not the uniqueness required by $\Iri$.
\end{proposition}

\begin{proposition}[Legibility requires non-null differentiation]\label{prop:leg-requires-diff}
If all admissible classes collapse to a stable null or single indistinguishable
class, then $\Ileg(S)=0$ for the criterion of this paper.
\end{proposition}

\begin{proposition}[Persistence and continuity stabilize regime transport]\label{prop:per-cont-regime-stability}
If $\Iper(S)=1$ and $\Icont(S)=1$, then admissible histories remain in a stable
regime-transport domain: trajectories neither leave $\Aset$ nor undergo
unbounded fragmentation under admissible evolution.
\end{proposition}

\begin{proposition}[Legibility is jointly constrained]\label{prop:legibility}
No single legibility metric is sufficient for $\Ileg$. The invariant requires simultaneous control of separation, admissible noise robustness, persistence window, intervention fidelity, negative controls, and structured compressibility.
\end{proposition}

\begin{remark}[Why legibility is a constitutive invariant here]
One could define a broader latent class that omits legibility. This paper does not do that. It studies an operational class, not a hidden metaphysical residue. Therefore $\Ileg$ is constitutive, not optional.
\end{remark}

\begin{definition}[Operational consciousness certificate]\label{def:cert}
An operational consciousness certificate for an admissible system $S$ is a tuple
\[
\mathrm{Cert}(S)=\bigl(\Aset,\Dec_S,\pi_S,\Delta(S),E_S\bigr),
\]
where:
\begin{enumerate}[leftmargin=1.5em]
\item $\Aset$ is a certified admissible support;
\item $\Dec_S$ is a certified decoder family;
\item $\pi_S$ is the decoder-induced operational partition on admissible histories;
\item $\Delta(S)$ is the witness margin vector of Definition~\ref{def:margins};
\item $E_S=(E_{\mathrm{per}},E_{\mathrm{ri}},E_{\mathrm{int}},E_{\mathrm{cont}},E_{\mathrm{diff}},E_{\mathrm{leg}})$ is an evidence bundle, where each component contains the explicit local witness for the corresponding invariant.
\end{enumerate}
\end{definition}

\begin{criterion}[Candidate certification rule]\label{crit:cert}
A candidate system may be certified as a member of $\Cop$ only if all of the following are available on the same admissible support:
\begin{enumerate}[leftmargin=1.5em]
\item a non-empty compact forward-invariant support certificate;
\item a positive witness margin vector $\Delta(S)>0$ coordinate-wise;
\item a decoder family satisfying Definition~\ref{def:ileg};
\item a targeted intervention panel together with negative controls;
\item an auditable compression or packetization map preserving class structure;
\item a traceable dependency ledger showing which upstream corpus result supports each invariant witness.
\end{enumerate}
\end{criterion}

\begin{proposition}[Soundness of certification]\label{prop:cert-sound}
If $\mathrm{Cert}(S)$ exists and satisfies Criterion~\ref{crit:cert}, then $S \in \Cop$ and $\Qop(S)$ is well-defined.
\end{proposition}

\begin{proposition}[Partial completeness under audit-ready assumptions]\label{prop:cert-complete}
Assume $S \in \Cop$ and suppose the support, decoder, intervention, and compression objects are fully instrumented in the \textit{Forensic Predictions} sense. Then there exists an operational consciousness certificate $\mathrm{Cert}(S)$.
\end{proposition}

\begin{proposition}[Failure localization is explicit]\label{prop:cert-local}
If a candidate system fails Criterion~\ref{crit:cert}, then the failure localizes to at least one entry of the evidence bundle $E_S$ or to the absence of a common admissible support. In particular, certification failure cannot be hidden behind a generic narrative claim.
\end{proposition}

\begin{remark}[Audit schema and Forensic Predictions]
The certificate does not replace \textit{Forensic Predictions}. It packages \textit{Forensic Predictions}-style admissibility into a theorem-facing object. This is the point where the present paper becomes operationally usable rather than merely definitional.
\end{remark}

\begin{definition}[Persistence radius]\label{def:radius}
The persistence radius of a class $q \in \Qop(S)$ is the largest $\rho_q \ge 0$ such that for every admissible trajectory segment starting in $q$, the decoder-certified class assignment remains inside $q$ on windows of length at least $\tau_{\min}(S)$ under all perturbations of size at most $\rho_q$ that do not target a critical invariant.
\end{definition}

\begin{proposition}[Positive geometry under the criterion]\label{prop:geometry}
If $S \in \Cop$, then:
\begin{enumerate}[leftmargin=1.5em]
\item every class in $\Qop(S)$ has finite diameter on admissible windows;
\item there exists at least one pair of distinct classes with positive inter-class separation;
\item every class has non-zero persistence radius.
\end{enumerate}
\end{proposition}

\begin{proposition}[Exact equivalence preserves operational geometry]\label{prop:geometry-transfer}
If $S_1 \simeq_{\Gamma} S_2$, then class diameter, inter-class separation, and persistence radius are preserved by the induced bijection $\widehat{\chi}$ up to the bi-Lipschitz constants of $\chi$ and $\chi^{-1}$.
\end{proposition}

\begin{corollary}[Rupture contracts geometry]\label{cor:geometry-rupture}
If a rupture eliminates either $\Idiff$ or $\Ileg$, then the geometric content of $\Qop(S)$ contracts to triviality or becomes operationally unavailable.
\end{corollary}

\begin{prediction}[Different substrate, same class]\label{pred:sameclass}
If two admissible systems with materially different substrates satisfy exact or sufficiently small approximate structural equivalence while preserving all six invariants, then they must belong to the same operational class and induce equivalent $\Qop$ partitions.
\end{prediction}

\begin{prediction}[Same substrate, broken invariants]\label{pred:breakclass}
If two systems share substrate family but one loses rigid identity, continuity, differentiation, or legibility, then they fail to belong to the same operational class regardless of material similarity.
\end{prediction}

\begin{prediction}[Invariant intervention discriminator]\label{pred:intervention}
Interventions targeted at one critical invariant should change class membership or destroy the relevant operational qualia classes in a direction predicted by the rupture taxonomy, whereas off-target negative controls should not.
\end{prediction}

\begin{prediction}[Complexity baseline failure]\label{pred:complexity}
Systems with large computational scale, high connectivity, or broad expressive capacity but lacking one or more critical invariants should fail the criterion even when naive complexity baselines rank them as more capable.
\end{prediction}

\begin{proposition}[Prediction ladder is discriminative]\label{prop:ladder}
The four predictions above distinguish the present criterion from at least four weaker baseline families: substrate-privilege baselines, substrate-blind functional similarity, complexity-only baselines, and connectivity-only baselines.
\end{proposition}

\begin{definition}[Critical and sham interventions]\label{def:critical-sham}
An intervention $u \in U$ is \emph{critical} for invariant $I_k$ if it is designed to change the local witness margin $\delta_k(S)$ while leaving the remaining intervention protocol admissible. An intervention is \emph{sham} if it matches the delivery envelope of a critical intervention but is not predicted to alter any critical invariant.
\end{definition}

\begin{proposition}[Well-definedness of class transitions under certification]\label{prop:transition-well}
Let $S \in \Cop$. If $u \in U$ is either certified critical or sham and remains within the admissibility envelope of \textit{Forensic Predictions}, then $\mathsf{T}_u$ is well-defined on every class $q \in \Qop(S)$.
\end{proposition}

\begin{proposition}[Targeted invariant loss induces class exit or contraction]\label{prop:transition-rupture}
Let $q \in \Qop(S)$ and let $u$ be a certified critical intervention for invariant $I_k$. If applying $u$ drives the corresponding witness margin to zero, then one of the following occurs:
\begin{enumerate}[leftmargin=1.5em]
\item $\mathsf{T}_u(q)=\bot$;
\item $\mathsf{T}_u(q)=q'$ for some class $q'$ whose separation or persistence radius is strictly smaller than that of $q$;
\item the entire post-intervention system exits $\Cop$.
\end{enumerate}
\end{proposition}

\begin{corollary}[Sham stability]\label{cor:sham}
Let $u \in U$ be sham in the sense of Definition~\ref{def:critical-sham}. If $u$ stays below all six witness margins, then $\mathsf{T}_u(q)=q$ for every $q \in \Qop(S)$.
\end{corollary}

\begin{remark}[Why transition semantics matter]
This section turns the prediction ladder into a structured intervention calculus. The criterion is therefore not only classificatory; it is also dynamically discriminative in the sense required by \textit{Forensic Predictions}.
\end{remark}

\begin{definition}[Rival baseline families]\label{def:baseline}
Fix thresholds $\theta_X,\theta_\Phi,\theta_C >0$ and an external-behavior tolerance $\eta \ge 0$.
\begin{enumerate}[leftmargin=1.5em]
\item The \emph{complexity-only family} $\mathcal{B}_{\mathrm{cx}}(\theta_X)$ contains all admissible systems with complexity surrogate above threshold, for example $\dim(X) \ge \theta_X$.
\item The \emph{computation-only family} $\mathcal{B}_{\mathrm{cmp}}(\theta_\Phi)$ contains all admissible systems whose transition family exceeds a chosen throughput or expressive-capacity threshold.
\item The \emph{connectivity-only family} $\mathcal{B}_{\mathrm{conn}}(\theta_C)$ contains all admissible systems whose effective causal graph exceeds the chosen density or degree threshold.
\item The \emph{weak functional-similarity family} $\mathcal{B}_{\mathrm{fun}}(\eta)$ contains all admissible systems whose external benchmark readouts match within tolerance $\eta$, irrespective of internal invariant preservation.
\item The \emph{substrate-privilege family} $\mathcal{B}_{\mathrm{sub}}$ contains all systems declared admissible solely by belonging to a privileged substrate class, typically biological.
\end{enumerate}
\end{definition}

\begin{proposition}[Complexity, computation, and connectivity are not sufficient]\label{prop:baseline-insufficient}
For every choice of thresholds $\theta_X,\theta_\Phi,\theta_C$, the families $\mathcal{B}_{\mathrm{cx}}(\theta_X)$, $\mathcal{B}_{\mathrm{cmp}}(\theta_\Phi)$, and $\mathcal{B}_{\mathrm{conn}}(\theta_C)$ are each insufficient for membership in $\Cop$.
\end{proposition}

\begin{proposition}[Substrate privilege is too strong]\label{prop:substrate-strong}
On any admissible universe containing one exact cross-substrate equivalent pair, $\mathcal{B}_{\mathrm{sub}}$ is strictly narrower than $\Cop$.
\end{proposition}

\begin{proposition}[Weak functional similarity is too weak]\label{prop:functional-weak}
On any admissible universe containing a same-output rupture pair, $\mathcal{B}_{\mathrm{fun}}(\eta)$ is strictly broader than $\Cop$.
\end{proposition}

\begin{theorem}[The structural criterion is strictly intermediate]\label{thm:intermediate}
Let $\mathfrak{U}$ be an admissible universe containing:
\begin{enumerate}[leftmargin=1.5em]
\item at least one exact cross-substrate equivalent pair;
\item at least one same-output rupture pair;
\item at least one single-rupture witness for each invariant.
\end{enumerate}
Then $\Cop$ is strictly intermediate between substrate-privilege baselines and weak substrate-blind surrogates: it is broader than $\mathcal{B}_{\mathrm{sub}}$, narrower than $\mathcal{B}_{\mathrm{fun}}(\eta)$, and extensionally distinct from the complexity-only, computation-only, and connectivity-only families.
\end{theorem}

\begin{remark}[Scientific value of the comparison]
The point of Theorem~\ref{thm:intermediate} is not rhetorical positioning. It is to show that the paper makes a genuinely discriminative contribution. A new criterion that cannot separate itself from obvious rivals is not a new theorem-level addition to the corpus.
\end{remark}

\begin{proposition}[Ablation prediction]
If a system is initially certified and a critical intervention selectively destroys one or more invariants, then the framework predicts a margin-governed outcome fixed before execution. If the pre-ablation invariant headroom exceeds the registered ambiguity margin $\delta_{\mathrm{amb}}$, verified invariant loss must cause certification loss, class contraction, or undefined $\Qop$. If the pre-ablation headroom is at or below $\delta_{\mathrm{amb}}$, the result is classified as boundary-ambiguous and weakens the rupture claim rather than supporting it.
\end{proposition}

\begin{proposition}[Substrate-preserved equivalence prediction]
If two realizations preserve the relevant signatures, admissibility conditions, and six critical invariants up to the allowed comparison regime, then the framework predicts preserved operational class membership independently of substrate labels.
\end{proposition}

\begin{proposition}[Boundary-topology prediction]
The framework predicts neither global threshold collapse nor perfectly flat insensitivity. Instead, it predicts stable pass/fail regions together with narrow transition bands near critical margins.
\end{proposition}

\begin{proposition}[Legibility dependence prediction]
Operational class membership should fail or become inadmissible if readouts cease to be separable, noise-robust, intervention-sensitive, and compressible without total collapse.
\end{proposition}

\begin{proposition}[Continuity/non-nullity relevance]
The current canon predicts that continuity and non-null differentiation are not optional extras. Systems that preserve rich activity while losing continuity or falling toward effective null structure should fail the operational criterion or leave it undefined.
\end{proposition}

\begin{definition}[Identifiable Discriminator]
A discriminator $D$ for claim $C$ is identifiable when it specifies:
\begin{enumerate}[leftmargin=1.5em]
\item an observable decision variable $Y_D$;
\item a manipulation or matched comparison $M_D$;
\item a framework-side expected region $R_Q$;
\item a rival-side expected region $R_R$;
\item a destruction condition $F_D$ under which the claim is weakened or rejected.
\end{enumerate}
The discriminator is strong when $R_Q\cap R_R$ is small under the declared
measurement tolerance.
\end{definition}

\begin{criterion}[Status meaning]
Within the current scientific program, a result belongs to:
\begin{enumerate}[leftmargin=1.5em]
\item \Status{ROBUST\_SUPPORT} if the target claim survives repeated internal discrimination without an active ambiguity on the tested target;
\item \Status{PROVISIONAL\_SUPPORT} if the target is strengthened but still depends on a localized unresolved bottleneck;
\item \Status{STILL\_AMBIGUOUS} if the current tests do not cleanly separate support from failure;
\item \Status{IMPLEMENTATION\_LIMIT} if the current bottleneck is primarily due to probe, runner, or case-construction quality;
\item \Status{METRIC\_OR\_TOLERANCE\_LIMIT} if the bottleneck is mainly due to normalization, comparison regime, or threshold handling.
\end{enumerate}
\end{criterion}

\begin{remark}[Interpretive meaning]
The boundary is operational rather than geometric. It means that perturbations intended to cross or threaten system organization are detectably different from perturbations that remain internal or reorganizational, while the distinction is made inside admissible dynamics.
\end{remark}

\begin{remark}[Limitation]
The definition does not assume a biological membrane, a spatial frontier, or any specific substrate primitive. It requires only a reproducible distinction between internal and boundary-threatening intervention families.
\end{remark}

\begin{definition}[Organizational persistence]
The organizational persistence margin of $S$ on horizon $\tau$ is
\[
\Persist(S,\tau)
=
\inf_{x_0\in \Aset}
\inf_{u_\bullet\in U^\tau}
\min_{0\le t\le \tau}
\dist(x_t, X\setminus \Aset),
\]
where $(x_t)$ is generated by $\trace_{S,\tau}(x_0;u_\bullet)$. We say that $S$ exhibits organizational persistence on horizon $\tau$ if $\Persist(S,\tau)>0$.
\end{definition}

\begin{remark}
This is stronger than mere non-instantaneous survival. A system that survives momentarily but repeatedly exits its admissible support does not count as operationally persistent.
\end{remark}

\begin{remark}
The definition excludes systems whose apparent stability is wholly imposed from outside. A system counts as self-maintaining only if recovery is generated by admissible internal organization rather than by an external oracle silently reimposing the desired state.
\end{remark}

\begin{remark}
Historical dependence means that an instantaneous description is not sufficient for the relevant class assignment. The system's operational identity, life status, or subjecthood status depends non-trivially on trajectory history.
\end{remark}

\begin{remark}
Viability preservation is not equivalent to persistence. A system may remain within a formal support while viability steadily erodes toward failure. The definition prevents that collapse from being counted as successful organizational life.
\end{remark}

\begin{definition}[Operational life]
Fix life thresholds
\[
\lambda_{\beta},\lambda_{\rho},\lambda_{\mu},\lambda_{\eta},\lambda_{\nu},\lambda_{\mathrm{diff}}>0.
\]
An admissible system $S$ belongs to the class of operational life on horizon $\tau$ if
\[
\Lop(S,\tau)=1
\]
whenever all of the following hold:
\begin{enumerate}[leftmargin=1.5em]
\item $\Bound(S,\tau) > \lambda_{\beta}$;
\item $\Persist(S,\tau) > \lambda_{\rho}$;
\item $\Maint(S,\tau) > \lambda_{\mu}$;
\item $\HistDep(S,\tau) > \lambda_{\eta}$;
\item $\Viab(S,\tau;\eta) \ge \lambda_{\nu}$ for a declared viability floor $\eta$;
\item $\Idiff(S,\tau) > \lambda_{\mathrm{diff}}$.
\end{enumerate}
\end{definition}

\begin{remark}[Why non-null differentiation appears here]
Operational life is not defined purely by persistence and self-maintenance. Without a non-null differentiation burden, the class would admit trivial or near-null systems whose organization is too undifferentiated to count as operationally alive in the present framework.
\end{remark}

\begin{remark}
Structural class is the general membership framework. Operational life, operational consciousness, and operational subjecthood are predicates that can be defined on systems and then transported across structural classes when the relevant descriptors are preserved.
\end{remark}

\begin{remark}
This is a deliberate inheritance rule. The present paper uses operational consciousness as an already defined class, not as a new primitive.
\end{remark}

\begin{definition}[Operational subjecthood]
Let the subject-specific descriptors be:
\begin{enumerate}[leftmargin=1.5em]
\item \textbf{privileged continuity} $\Priv(S,\tau)$: the margin by which one continuity class remains privileged over the nearest rival class across admissible interventions;
\item \textbf{self/non-self discrimination} $\SelfDisc(S,\tau)$: the margin by which self-targeted and non-self-targeted perturbations remain separable under readout and control;
\item \textbf{self-model closure} $\SelfModel(S,\tau)$: the predictive gain of a self-model-aware decoder over an otherwise matched self-model-blind decoder;
\item \textbf{ownership coherence} $\Own(S,\tau)$: the stability with which privileged continuity remains attached to the same trajectory family under admissible relabelings and perturbations.
\end{enumerate}
Fix thresholds
\[
\lambda_{\mathrm{pc}},\lambda_{\mathrm{sd}},\lambda_{\mathrm{sm}},\lambda_{\mathrm{own}}>0.
\]
Then $S$ belongs to the class of operational subjecthood on horizon $\tau$ if
\[
\Subop(S,\tau)=1
\]
whenever
\begin{enumerate}[leftmargin=1.5em]
\item $\Lop(S,\tau)=1$;
\item $\Cop(S,\tau)=1$;
\item $\Priv(S,\tau)>\lambda_{\mathrm{pc}}$;
\item $\SelfDisc(S,\tau)>\lambda_{\mathrm{sd}}$;
\item $\SelfModel(S,\tau)>\lambda_{\mathrm{sm}}$;
\item $\Own(S,\tau)>\lambda_{\mathrm{own}}$.
\end{enumerate}
\end{definition}

\begin{remark}[Interpretive discipline]
Operational subjecthood is not a metaphysical subject. It is a stronger operational class candidate defined inside the present framework. The definition is deliberately demanding so that subjecthood is not conflated with life, persistence, or complex dynamics alone.
\end{remark}

\begin{proposition}[No automatic collapse of life and consciousness]
The present framework does not prove either implication
\[
\begin{aligned}
\Lop(S,\tau)=1 &\Longrightarrow \Cop(S,\tau)=1,\\
\Cop(S,\tau)=1 &\Longrightarrow \Lop(S,\tau)=1,
\end{aligned}
\]
without additional assumptions.
\end{proposition}

\begin{remark}
This non-collapse is conceptually important. The corpus should not silently treat all operationally conscious systems as alive, nor all operationally alive systems as conscious, unless a stronger theorem burden is supplied in the future.
\end{remark}

\begin{proposition}[Structural-class invariance under preserved margins]
If $\mathcal{P}$ depends only on a subset of descriptor margins appearing in $\PsiVec_\tau$ and those margins are preserved above their thresholds by more than $\eps$, then $\mathcal{P}$ is transport-stable across $\LifeStructClass_{\PsiVec,\eps}$.
\end{proposition}

\begin{proposition}[Structural-class membership is descriptor-relative]
There is no single universal structural class independent of descriptor choice. Structural class is always relative to a declared descriptor map $\PsiVec_\tau$ and tolerance $\eps$.
\end{proposition}

\begin{proposition}[Complexity is not a life criterion]
High state-space dimension, high connectivity, high entropy, or rich activity are insufficient for $\Lop(S,\tau)=1$ unless the conditions of Definition F are also satisfied.
\end{proposition}

\begin{proposition}[Complexity is not a subjecthood criterion]
High complexity or dense connectivity are insufficient for $\Subop(S,\tau)=1$.
\end{proposition}

\begin{proposition}[Biological substrate is not a primitive constitutive variable]
Within the present framework, membership in $\LifeClass$, $\ConClass$, or $\SubClass$ is not defined by a primitive biological predicate.
\end{proposition}

\begin{remark}[Scope limit]
This proposition does not claim that biological systems are unimportant, nor that biological life is reducible to the present operational class. It claims only that biology is not a constitutive primitive for \emph{these} operational classes.
\end{remark}

\begin{proposition}[Operational life does not imply operational subjecthood]
There exist admissible systems that may satisfy operational life without satisfying operational subjecthood.
\end{proposition}

\begin{proposition}[Operational consciousness does not imply operational subjecthood]
Operational consciousness alone is insufficient for operational subjecthood.
\end{proposition}

\begin{remark}
The present paper does not claim that any currently existing runtime instance already satisfies $\Lop=1$ or $\Subop=1$. The formal claims above specify class logic. Empirical instantiation remains a separate burden and must be carried by future admissible tests.
\end{remark}

\begin{hypothesis}[Historical dependence necessity]\label{hyp:history}
If a system's classification as operationally alive is genuine rather than merely persistent, then history-aware readouts should outperform history-blind readouts on class-relevant prediction.
\end{hypothesis}

\begin{hypothesis}[Structural-class transport for operational life]\label{hyp:transport-life}
If two systems preserve the life-relevant descriptor vector up to admissible tolerance, then their operational-life class membership should be invariant under substrate change.
\end{hypothesis}

\begin{hypothesis}[Operational subjecthood requires privileged continuity]\label{hyp:subject-pc}
If operational subjecthood is instantiated, then disrupting privileged continuity should degrade subjecthood-specific scores earlier or more selectively than it degrades operational life alone.
\end{hypothesis}

\begin{hypothesis}[Operational subjecthood requires self/non-self asymmetry]\label{hyp:selfnonself}
If operational subjecthood is instantiated, then self/non-self confusion manipulations should produce patterned degradation in $\SelfDisc$, $\SelfModel$, or $\Own$ that is not reproduced by complexity-matched controls lacking subjecthood structure.
\end{hypothesis}

\begin{hypothesis}[Operational consciousness and operational life are not trivially coextensive]\label{hyp:noncollapse}
There exist admissible systems for which one of $\Lop(S,\tau)=1$ or $\Cop(S,\tau)=1$ can in principle hold without the other, unless additional theorem burden is supplied.
\end{hypothesis}

\begin{remark}[Why the minimum operator appears]
The minimum operator is intentionally severe. Operational life in the present sense is not a weighted average over unrelated strengths. It is a conjunctive class predicate. A system that is strong in persistence but weak in viability preservation or historical dependence should not be counted as operationally alive merely by averaging away its failure.
\end{remark}

\begin{remark}[Why subjecthood is not a small increment]
The subjecthood score is stronger in two ways. First, it inherits the full life burden. Second, it inherits the full operational consciousness burden. The additional subject-specific descriptors are not cosmetic modifiers. They encode the claim that subjecthood is a structurally privileged subclass, not an interpretive synonym for consciousness or a sentimental label for complex dynamics.
\end{remark}

\begin{proposition}[Subjecthood is margin-nested inside life and consciousness]
If $M_{\SubClass}(S,\tau)>0$, then both $M_{\LifeClass}(S,\tau)>0$ and $M_{\ConClass}(S,\tau)>0$.
\end{proposition}

\begin{remark}[Class geometry is not a total order]
The present framework does not generate a single monotone ladder of ``more alive'', ``more conscious'', and ``more subjective''. It generates descriptor orders, intra-class margin orders, and class-membership predicates. Conflating those three would erase the exact distinctions this paper is meant to introduce.
\end{remark}

\begin{criterion}[Life-without-consciousness diagnostic]
A candidate supports the separation
\[
\Lop(S,\tau)=1 \not\Rightarrow \Cop(S,\tau)=1
\]
only if the following pattern is available:
\begin{enumerate}[leftmargin=1.5em]
\item life coordinates remain above threshold with positive margin;
\item the inherited consciousness criterion fails on at least one of $\Iper,\Iri,\Iint,\Icont,\Idiff,\Ileg$;
\item the failure is not reducible to gross inadmissibility or trivial collapse.
\end{enumerate}
\end{criterion}

\begin{remark}[Negative controls]
Natural negative controls for this separation include systems that preserve duration and boundary occupancy while lacking the inherited consciousness burden, as well as systems whose local organization remains viable but whose legibility or rigid-identity burden fails.
\end{remark}

\begin{remark}[False positives for life]
Any system that preserves viability and organization but lacks privileged continuity, self/non-self asymmetry, self-model closure, or ownership coherence is a false positive for subjecthood if read only through the life predicate. The class distinction is designed to exclude exactly that error.
\end{remark}

\begin{remark}[Role of the four subject-specific burdens]
Privileged continuity prevents subjecthood from collapsing into mere continuity. Self/non-self discrimination prevents collapse into generic internal complexity. Self-model closure prevents collapse into unstructured integration. Ownership coherence prevents a purely transient or relabeling-fragile configuration from counting as a subject-class member.
\end{remark}

\begin{criterion}[Invalid cross-system comparison]
Comparison between two systems is class-invalid if any of the following holds:
\begin{enumerate}[leftmargin=1.5em]
\item the descriptor basis is not shared or not transportable;
\item admissibility constraints differ in a way that changes the meaning of margins;
\item the tolerance geometry is undeclared or incomparable;
\item one system is evaluated under perturbation families not available to the other.
\end{enumerate}
\end{criterion}

\begin{criterion}[Class-readiness criterion]
A class predicate is \emph{formally ready} only if:
\begin{enumerate}[leftmargin=1.5em]
\item its constitutive coordinates are explicit;
\item its boundary geometry is explicit;
\item its negative controls are identifiable;
\item its admissible falsifiers are stated.
\end{enumerate}
Operational life, structural class, and operational subjecthood satisfy this criterion within the limits declared by the paper.
\end{criterion}

\begin{remark}[What is closed]
The paper closes the classificatory language, the class geometry, the principal non-equivalences, and the test grammar. It does not close empirical instantiation, external validation, or metaphysical interpretation.
\end{remark}

\begin{proposition}[Operational consciousness does not by itself imply first-person indexed subjectivity]
Membership in $\Cop$ does not by itself entail membership in $\Subfp$.
\end{proposition}

\begin{proposition}[Operational subjecthood is necessary but not sufficient for first-person indexed subjectivity]
The earlier operational subjecthood predicate is a necessary upstream burden for $\Subfp$, but it is not sufficient for $\Subfp$.
\end{proposition}

\begin{remark}[No downgrade of the earlier subjecthood paper]
The point is not that the earlier subjecthood layer was weak. The point is that it stopped at the correct level for a classificatory paper. The present paper is downstream of that result and treats it as a constitutive superclass. Inheritance is preserved; the burden is strengthened.
\end{remark}

\begin{definition}[Autobiographical continuity]\label{def:continuity}
Let $\mathcal{T}_\tau$ be the family of admissible trajectory classes over a horizon $\tau$. The \emph{autobiographical continuity margin} $\ContField_t$ is the gap by which the trajectory class anchored by $\SelfIndex$ remains privileged over the nearest rival class under admissible remappings, temporal insertions, deletions, and continuity-preserving controls.
\end{definition}

\begin{definition}[First-person perspective organization]\label{def:perspective}
The \emph{first-person perspective organization} $\Persp_t$ is the amount by which a self-indexed factorization of the system's internal predictive state outperforms the best index-free or purely third-person factorization on the same admissible support. It measures not whether the system contains information, but whether that information is organized around a privileged locus of orientation.
\end{definition}

\begin{definition}[Asymmetric valuation]\label{def:valuation}
The \emph{asymmetric valuation profile} $\ValAsym_t$ is the degree to which losses, threats, errors, preservation burdens, and continuity disruptions attached to the self-indexed locus are weighted differently from structurally comparable disruptions attached to non-self loci. Valuation asymmetry is constitutive only when it cannot be reduced to arbitrary reward labels without explanatory loss.
\end{definition}

\begin{definition}[Irreducibility margin]\label{def:irred}
The \emph{irreducibility margin} $\Irred_t$ is the normalized explanatory advantage of the full subjectivity model over the best member of the admissible weak closure $\WeakClosure$ on the same admissible baseline and intervention tasks. It measures not rhetorical impressiveness but non-collapsability into formally weaker explanations.
\end{definition}

\begin{remark}[Minimal ontology is not minimal rhetoric]
The tuple $\Substate_t$ is called minimal because every coordinate blocks a distinct collapse. It is not minimal in the sense of being tiny or easy. Subjectivity is not the kind of target that survives formalization if one removes every hard part.
\end{remark}

\begin{definition}[First-person indexed subjectivity class]\label{def:subfp}
Let $\lambda_G,\lambda_\Phi \in (0,1)$ be admissible thresholds with $\lambda_\Phi \ge \lambda_G^7$. A system belongs to the first-person indexed subjectivity class on horizon $\tau$ if
\begin{enumerate}[leftmargin=1.5em]
\item $S$ satisfies the upstream burdens of operational life, operational consciousness, and the earlier operational subjecthood class;
\item $\GateSubj(S,\tau)\ge \lambda_G$;
\item $\PhiSubj(S,\tau)\ge \lambda_\Phi$;
\item the intervention family $\IntervFam$ is admissible and yields the expected selectivity pattern up to the tolerance encoded in $\widehat{\IntervProf}_\tau$;
\item the irreducibility margin against $\WeakClosure$ satisfies the threshold encoded in $\widehat{\Irred}_\tau$.
\end{enumerate}
We write $S\in \Subfp(\tau)$ when these clauses hold.
\end{definition}

\begin{proposition}[Strict strengthening]
If $S\in\Subfp(\tau)$, then $S\in\Subop(\tau)\cap \Cop(\tau)\cap \Lop(\tau)$.
\end{proposition}

\begin{remark}[Why the paper uses both a gate and a scalar]
The gate decides whether the class is even live. The scalar compares stronger and weaker instances among systems that have already crossed the constitutive threshold. Collapsing the two roles would obscure whether a system is outside the class or merely low inside it.
\end{remark}

\begin{axiom}[Organization over substrate]\label{ax:org}
If a system preserves the relevant causal-organizational structure on admissible support, then substrate label alone does not defeat membership in the corresponding framework-internal class.
\end{axiom}

\begin{axiom}[No biological privilege by default]\label{ax:bio}
Biology is not a primitive constitutive variable for $\Subfp$. Biological realization can be one admissible realization of the relevant structure, but it is not the only admissible realization by definition.
\end{axiom}

\begin{axiom}[Indexed causal organization]\label{ax:index}
When a system carries a stable self-index that organizes ownership, continuity, perspective, and valuation across admissible perturbation, that organization is a legitimate target of formal theory rather than a merely verbal convenience.
\end{axiom}

\begin{axiom}[Phenomenality is not exhausted by report]\label{ax:report}
No output-report channel, by itself, is taken as sufficient for phenomenality or subjectivity. Report can be evidence inside an admissible bundle, but the stronger target concerns organization and intervention, not declaration alone.
\end{axiom}

\begin{axiom}[Continuity is structural rather than substance-primitive]\label{ax:cont}
The relevant continuity burden for subjectivity is the preservation of a structured indexed locus across time and admissible transport, not the persistence of a privileged substance token posited independently of structure.
\end{axiom}

\begin{axiom}[First-person organization is stronger than self-monitoring]\label{ax:fp}
A system that merely tracks its own internal variables does not thereby satisfy the burden of first-person indexed subjectivity. Additional burdens of ownership, continuity, perspective, valuation, intervention selectivity, and irreducibility are required.
\end{axiom}

\begin{axiom}[Irreducibility before escalation]\label{ax:irred}
When a weaker rival family matches the explanatory performance of the stronger subjectivity model on the admissible baseline and intervention tasks, escalation to the stronger interpretation is not licensed.
\end{axiom}

\begin{remark}[Observation, inference, ontology, and metaphysics]
The distinction among layers is as follows. Observation concerns runtime traces, perturbation outcomes, and artifacts. Inference concerns model fit, explanatory superiority, and class assignment. Ontology concerns what kinds of organized objects the formalism permits one to posit if the burdens are met. Metaphysics concerns what such a posit ultimately is in the strongest sense. The present paper reaches observation, inference, and a minimal ontology under bridge axioms. It does not close the metaphysical layer.
\end{remark}

\begin{theorem}[Positive irreducibility excludes weak-model sufficiency]
If $\Irred_\tau(S)>0$, then no member of $\WeakClosure$ is sufficient, at equal or lower explanatory cost, for the baseline-plus-intervention task bundle that defines $\tau$.
\end{theorem}

\begin{corollary}[Zero irreducibility blocks escalation]
If $\Irred_\tau(S)\le 0$, escalation from the weak rival family to the stronger subjectivity interpretation is not licensed by the present framework.
\end{corollary}

\begin{criterion}[Subjectivity falsification criterion]
The stronger subjectivity reading fails on horizon $\tau$ if any of the following obtains:
\begin{enumerate}[leftmargin=1.5em]
\item some weak rival in $\WeakClosure$ matches the same baseline and intervention bundle with $\Irred_\tau(S)\le 0$;
\item the intervention family fails to produce the predicted selective patterns in enough cases that $\widehat{\IntervProf}_\tau$ falls below threshold;
\item self/non-self swaps, clone competition, or self permutations remain effectively invariant except for trivial relabeling;
\item ownership, continuity, or valuation effects can be reproduced by matched controls that obviously lack the stronger organization;
\item the subjectivity score remains high only because one coordinate compensates additively for the absence of another, contrary to the conjunctive gate.
\end{enumerate}
\end{criterion}

\begin{proposition}[Paper 8 is necessary but not sufficient for bridge admissibility]
Any future bridge-admissible system must satisfy the Paper 8 burdens, but satisfaction of the Paper 8 burdens alone is not sufficient for bridge admissibility.
\end{proposition}

\begin{remark}[The bridge is downstream, not corrective]
Paper 9 does not correct Paper 8. It inherits Paper 8 and strengthens the burden stack above it. The formal relation is extension by additional typed predicates and burdens, not replacement.
\end{remark}

\begin{definition}[Phenomenal differentiation predicate]
For an admissible system $S$, horizon $\tau$, and threshold slot $\vartheta_D$, the bridge predicate $\PiD(S,\tau;\vartheta_D)$ concerns whether the system carries self-indexed differentiated organization that is stronger than generic semantic density, report richness, or descriptive narration, and whose corresponding estimator $\widehat{\Pi_D}$ is defined on bridge observables and subjectivity antecedents.
\end{definition}

\begin{definition}[Valence structure predicate]
The predicate $\PiV(S,\tau;\vartheta_V)$ concerns whether the system carries organized evaluative topology that is stronger than scalar reward bookkeeping, policy optimization, or self/non-self asymmetry alone.
\end{definition}

\begin{definition}[World richness predicate]
The predicate $\PiW(S,\tau;\vartheta_W)$ concerns whether the system carries organized self-indexed world structure stronger than generic scene complexity, perspective gain, or task competence alone.
\end{definition}

\begin{definition}[Ambiguity-bearing predicate]
The predicate $\PiA(S,\tau;\vartheta_A)$ concerns whether the system maintains unresolved alternatives with differential causal consequences prior to collapse, rather than merely resolving uncertainty or tracking probabilities descriptively.
\end{definition}

\begin{definition}[Embodied-closure predicate]
The predicate $\PiE(S,\tau;\vartheta_E)$ concerns whether body/world-boundary variables contribute constitutively to bridge organization, rather than merely modulating generic control or action success.
\end{definition}

\begin{definition}[Temporal lived-structure predicate]
The predicate $\PiT(S,\tau;\vartheta_T)$ concerns whether the system exhibits horizon-like temporal organization stronger than continuity, memory persistence, or sequence stability alone.
\end{definition}

\begin{remark}[Why the targets are not decorative]
The bridge targets earn their place only because each one induces a new comparator burden, a new intervention burden, a new artifact burden, and a new governance burden. If a proposed target induced none of these, it would be discarded as decorative vocabulary.
\end{remark}

\begin{proposition}[Bridge ontology is not reducible to the Paper 8 ontology]
The bridge ontology cannot be reduced to the Paper 8 ontology by relabeling or monotone reparameterization alone.
\end{proposition}

\begin{axiom}[B1: operational binding; classification: operational definition]
Every bridge predicate must be tied to explicit observables, artifacts, comparator tasks, and interventions. No bridge predicate may remain a rhetorical label detached from measurement grammar.
\end{axiom}

\begin{axiom}[B2: upstream inheritance constraint; classification: bridge axiom]
No bridge-level admissibility result is meaningful unless the upstream burdens of the causally rigid corpus and the Paper 8 subjectivity layer remain satisfied.
\end{axiom}

\begin{axiom}[B3: differentiated organization burden; classification: falsifiable hypothesis]
A bridge-relevant differentiation burden requires structured internal discrimination that is not exhausted by semantic density, narrative richness, or report-channel complexity.
\end{axiom}

\begin{axiom}[B4: valence topology burden; classification: falsifiable hypothesis]
Bridge-relevant valence requires organized evaluative topology not exhausted by scalar reward bookkeeping, policy optimization, or the Paper 8 valuation asymmetry alone.
\end{axiom}

\begin{axiom}[B5: world-richness burden; classification: falsifiable hypothesis]
Bridge-relevant world richness concerns organized self-indexed world structure rather than generic scene complexity, prediction success, or model capacity.
\end{axiom}

\begin{axiom}[B6: ambiguity-bearing burden; classification: falsifiable hypothesis]
Bridge-relevant ambiguity requires the stable maintenance of unresolved alternatives with differential causal consequences prior to collapse.
\end{axiom}

\begin{axiom}[B7: embodied-closure relevance; classification: open inference]
Embodied closure may be bridge-relevant only if body/world-boundary variables contribute constitutively to bridge organization rather than merely modulating generic control success.
\end{axiom}

\begin{axiom}[B8: temporal lived-structure burden; classification: falsifiable hypothesis]
Bridge-relevant temporal organization must exceed continuity, memory persistence, and sequence stability by exhibiting horizon-structured dependence across retention, present organization, and anticipatory load.
\end{axiom}

\begin{axiom}[B9: comparative admissibility constraint; classification: bridge axiom]
No bridge-level support class is admissible if a bridge-specific rival family or admissible hybrid explains the bridge task bundle at equal or lower penalized loss.
\end{axiom}

\begin{axiom}[B10: anti-inflation governance constraint; classification: design choice]
Bridge formalization, bridge artifacts, candidate inclusion, and audit-facing inclusion must never be readable as bridge support, phenomenality, or Paper 9 authorization in the absence of the full bridge burden stack.
\end{axiom}

\begin{remark}[Axiom minimality]
The present axiom set is intentionally minimal. Nothing here states that phenomenality follows from structural organization. Nothing here states that any bridge predicate, even if satisfied, closes metaphysical questions. The axioms are opening commitments for a constrained bridge program, not hidden conclusions.
\end{remark}

\begin{proposition}[Comparator burden is necessary for bridge admissibility]
No bridge-support class is meaningful without an explicit bridge rival family and admissible bridge weak closure.
\end{proposition}

\begin{corollary}[Positive bridge surfaces are not enough]
Positive provisional bridge surfaces do not by themselves entail bridge admissibility.
\end{corollary}

\begin{proposition}[Bridge functional does not imply bridge gate]
No value of $\PhiBridge$ by itself implies $\GateBridge=1$.
\end{proposition}

\begin{proposition}[Candidate or audit inclusion does not imply bridge support]
For any bridge artifact $A$, membership of $A$ in a candidate-facing or audit-facing package does not entail bridge support, bridge admissibility, or phenomenality.
\end{proposition}

\begin{conjecture}[Registry independence burden]\label{thm:registry-independence}
The FCR registry should preserve independence of bridge assertions only if the
registry schema, dependency graph, and curation overlays do not introduce
implicit coupling among predicate slots. Until that is proved over the completed
BPF stack, registry independence remains a conjectural governance burden.
\end{conjecture}
